export async function revokeApiKey(
  db: Database,
  workspaceId: string,
  apiKeyId: string,
): Promise<ApiKey> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const [row] = await scopedDb
      .update(schema.apiKeys)
      .set({
        revokedAt: new Date(),
        updatedAt: new Date(),
      })
      .where(and(eq(schema.apiKeys.workspaceId, workspaceId), eq(schema.apiKeys.id, apiKeyId)))
      .returning();
    if (!row) {
      throw new Error(`API key not found: ${apiKeyId}`);
    }
    return mapApiKey(row);
  });
}

export async function findActiveApiKeyByHash(
  db: Database,
  keyHash: string,
): Promise<ApiKey | null> {
  return await db.transaction(async (tx) => {
    await tx.execute(sql`select set_config('opengeni.api_key_hash', ${keyHash}, true)`);
    const [row] = await tx
      .select()
      .from(schema.apiKeys)
      .where(
        and(
          eq(schema.apiKeys.keyHash, keyHash),
          sql`${schema.apiKeys.revokedAt} is null`,
          sql`(${schema.apiKeys.expiresAt} is null or ${schema.apiKeys.expiresAt} > now())`,
        ),
      )
      .limit(1);
    if (!row) {
      return null;
    }
    const now = new Date();
    await tx
      .update(schema.apiKeys)
      .set({ lastUsedAt: now, updatedAt: now })
      .where(eq(schema.apiKeys.id, row.id));
    return mapApiKey({ ...row, lastUsedAt: now });
  });
}

export type GitHubInstallation = {
  id: string;
  accountId: string;
  workspaceId: string;
  installationId: number;
  githubAccountId: number | null;
  accountLogin: string | null;
  accountType: string | null;
  repositoryScope: GitHubRepositoryScope;
  linkedBySubjectId: string | null;
  githubActorId: number | null;
  githubActorLogin: string | null;
  authorityKind: GitHubInstallationAuthorityKind | null;
  authorityCheckedAt: string | null;
  authorityExpiresAt: string | null;
  authorityNonce: string | null;
  createdAt: string;
  updatedAt: string;
};

export type GitHubInstallationAccess = GitHubInstallation & {
  repositoryIds: number[];
};

export class GitHubInstallationAuthorityCommitError extends Error {
  constructor() {
    super("GitHub installation authority expired before the binding transaction completed");
  }
}

const githubInstallationAuthorityMaxAgeMs = 10 * 60_000;

/**
 * True only for a binding created by the owner-authority transaction. Legacy
 * installation rows remain visible for audit/unlink, but can never make a
 * workspace healthy, enumerate repositories, or authorize a token mint.
 *
 * `authorityExpiresAt` is the expiry of the consumed proof, not of the durable
 * delegation. A binding remains delegated after that instant; GitHub's live
 * installation/repository checks govern its ongoing usability.
 */
export function hasAuditableGitHubInstallationAuthority(
  installation: GitHubInstallationAccess,
): boolean {
  const checkedAt = installation.authorityCheckedAt
    ? Date.parse(installation.authorityCheckedAt)
    : Number.NaN;
  const expiresAt = installation.authorityExpiresAt
    ? Date.parse(installation.authorityExpiresAt)
    : Number.NaN;
  const common =
    installation.repositoryScope === "selected" &&
    installation.repositoryIds.length > 0 &&
    installation.repositoryIds.every((id) => Number.isSafeInteger(id) && id > 0) &&
    installation.githubAccountId !== null &&
    Number.isSafeInteger(installation.githubAccountId) &&
    installation.githubAccountId > 0 &&
    Boolean(installation.accountLogin) &&
    installation.githubActorId !== null &&
    Number.isSafeInteger(installation.githubActorId) &&
    installation.githubActorId > 0 &&
    Boolean(installation.githubActorLogin) &&
    Boolean(installation.linkedBySubjectId) &&
    Boolean(installation.authorityNonce) &&
    Number.isFinite(checkedAt) &&
    Number.isFinite(expiresAt) &&
    checkedAt < expiresAt;
  if (!common) {
    return false;
  }
  return installation.authorityKind === "personal_owner"
    ? installation.accountType === "User" &&
        installation.githubActorId === installation.githubAccountId
    : installation.authorityKind === "organization_owner" &&
        installation.accountType === "Organization";
}

export async function upsertGitHubInstallation(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    installationId: number;
    accountLogin?: string | null;
    accountType?: string | null;
    linkedBySubjectId?: string | null;
  },
): Promise<GitHubInstallation> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      const [row] = await scopedDb
        .insert(schema.githubInstallations)
        .values({
          accountId: input.accountId,
          workspaceId: input.workspaceId,
          installationId: input.installationId,
          accountLogin: input.accountLogin ?? null,
          accountType: input.accountType ?? null,
          linkedBySubjectId: input.linkedBySubjectId ?? null,
        })
        .onConflictDoUpdate({
          target: [
            schema.githubInstallations.workspaceId,
            schema.githubInstallations.installationId,
          ],
          set: {
            accountId: input.accountId,
            accountLogin: input.accountLogin ?? null,
            accountType: input.accountType ?? null,
            ...(input.linkedBySubjectId !== undefined
              ? { linkedBySubjectId: input.linkedBySubjectId }
              : {}),
            updatedAt: new Date(),
          },
          // This legacy metadata helper cannot mutate an owner-authorized row.
          // New bindings use bindAuthorizedGitHubInstallationRepositories.
          setWhere: isNull(schema.githubInstallations.authorityNonce),
        })
        .returning();
      if (!row) {
        throw new Error("Failed to upsert GitHub installation");
      }
      return mapGitHubInstallation(row);
    },
  );
}

export async function bindGitHubInstallationRepositories(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    installationId: number;
    accountLogin?: string | null;
    accountType?: string | null;
    linkedBySubjectId: string;
    repositoryIds: number[];
  },
): Promise<GitHubInstallationAccess> {
  if (!Number.isSafeInteger(input.installationId) || input.installationId <= 0) {
    throw new Error("GitHub installation id must be a positive safe integer");
  }
  const repositoryIds = [...new Set(input.repositoryIds)];
  if (
    repositoryIds.length === 0 ||
    repositoryIds.some((id) => !Number.isSafeInteger(id) || id <= 0)
  ) {
    throw new Error("GitHub repository ids must contain at least one positive safe integer");
  }
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (tx) => {
        const [row] = await tx
          .insert(schema.githubInstallations)
          .values({
            accountId: input.accountId,
            workspaceId: input.workspaceId,
            installationId: input.installationId,
            accountLogin: input.accountLogin ?? null,
            accountType: input.accountType ?? null,
            repositoryScope: "selected",
            linkedBySubjectId: input.linkedBySubjectId,
          })
          .onConflictDoUpdate({
            target: [
              schema.githubInstallations.workspaceId,
              schema.githubInstallations.installationId,
            ],
            set: {
              accountId: input.accountId,
              accountLogin: input.accountLogin ?? null,
              accountType: input.accountType ?? null,
              repositoryScope: "selected",
              linkedBySubjectId: input.linkedBySubjectId,
              updatedAt: new Date(),
            },
            // Preserve the immutable authority + allowlist audit boundary.
            setWhere: isNull(schema.githubInstallations.authorityNonce),
          })
          .returning();
        if (!row) {
          throw new Error("Failed to bind GitHub installation");
        }
        await tx
          .delete(schema.githubInstallationRepositories)
          .where(
            and(
              eq(schema.githubInstallationRepositories.workspaceId, input.workspaceId),
              eq(schema.githubInstallationRepositories.installationId, input.installationId),
            ),
          );
        for (let offset = 0; offset < repositoryIds.length; offset += 1_000) {
          await tx.insert(schema.githubInstallationRepositories).values(
            repositoryIds.slice(offset, offset + 1_000).map((repositoryId) => ({
              accountId: input.accountId,
              workspaceId: input.workspaceId,
              installationId: input.installationId,
              repositoryId,
            })),
          );
        }
        return { ...mapGitHubInstallation(row), repositoryIds };
      }),
  );
}

export async function bindAuthorizedGitHubInstallationRepositories(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    installationId: number;
    githubAccountId: number;
    accountLogin: string | null;
    accountType: string | null;
    linkedBySubjectId: string;
    githubActorId: number;
    githubActorLogin: string;
    authorityKind: GitHubInstallationAuthorityKind;
    authorityCheckedAt: Date;
    authorityExpiresAt: Date;
    authorityNonce: string;
    repositoryIds: number[];
  },
): Promise<GitHubInstallationAccess | null> {
  if (!Number.isSafeInteger(input.installationId) || input.installationId <= 0) {
    throw new Error("GitHub installation id must be a positive safe integer");
  }
  if (!Number.isSafeInteger(input.githubAccountId) || input.githubAccountId <= 0) {
    throw new Error("GitHub account id must be a positive safe integer");
  }
  if (!Number.isSafeInteger(input.githubActorId) || input.githubActorId <= 0) {
    throw new Error("GitHub actor id must be a positive safe integer");
  }
  const authorityCheckedAtMs = input.authorityCheckedAt.getTime();
  const authorityExpiresAtMs = input.authorityExpiresAt.getTime();
  if (
    !Number.isFinite(authorityCheckedAtMs) ||
    !Number.isFinite(authorityExpiresAtMs) ||
    authorityCheckedAtMs >= authorityExpiresAtMs ||
    authorityExpiresAtMs - authorityCheckedAtMs > githubInstallationAuthorityMaxAgeMs ||
    !input.authorityNonce ||
    !input.githubActorLogin.trim() ||
    !input.accountLogin?.trim() ||
    !input.linkedBySubjectId.trim() ||
    (input.authorityKind !== "personal_owner" && input.authorityKind !== "organization_owner") ||
    (input.authorityKind === "personal_owner" &&
      (input.accountType !== "User" || input.githubActorId !== input.githubAccountId)) ||
    (input.authorityKind === "organization_owner" && input.accountType !== "Organization")
  ) {
    throw new Error("GitHub installation authority proof is invalid or expired");
  }
  const repositoryIds = [...new Set(input.repositoryIds)];
  if (
    repositoryIds.length === 0 ||
    repositoryIds.length !== input.repositoryIds.length ||
    repositoryIds.some((id) => !Number.isSafeInteger(id) || id <= 0)
  ) {
    throw new Error(
      "GitHub repository ids must be a nonempty, unique list of positive safe integers",
    );
  }
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (tx) => {
        await assertGitHubAuthorityWindowOpen(
          tx,
          input.authorityCheckedAt,
          input.authorityExpiresAt,
        );
        await tx
          .delete(schema.integrationOauthStateNonces)
          .where(
            and(
              eq(schema.integrationOauthStateNonces.workspaceId, input.workspaceId),
              lt(schema.integrationOauthStateNonces.expiresAt, input.authorityCheckedAt),
            ),
          );
        const consumed = await tx
          .insert(schema.integrationOauthStateNonces)
          .values({
            accountId: input.accountId,
            workspaceId: input.workspaceId,
            subjectId: input.linkedBySubjectId,
            nonce: input.authorityNonce,
            expiresAt: input.authorityExpiresAt,
            usedAt: input.authorityCheckedAt,
          })
          .onConflictDoNothing({
            target: schema.integrationOauthStateNonces.nonce,
          })
          .returning({ nonce: schema.integrationOauthStateNonces.nonce });
        if (consumed.length === 0) {
          return null;
        }

        const [row] = await tx
          .insert(schema.githubInstallations)
          .values({
            accountId: input.accountId,
            workspaceId: input.workspaceId,
            installationId: input.installationId,
            githubAccountId: input.githubAccountId,
            accountLogin: input.accountLogin,
            accountType: input.accountType,
            repositoryScope: "selected",
            linkedBySubjectId: input.linkedBySubjectId,
            githubActorId: input.githubActorId,
            githubActorLogin: input.githubActorLogin,
            authorityKind: input.authorityKind,
            authorityCheckedAt: input.authorityCheckedAt,
            authorityExpiresAt: input.authorityExpiresAt,
            authorityNonce: input.authorityNonce,
          })
          .onConflictDoUpdate({
            target: [
              schema.githubInstallations.workspaceId,
              schema.githubInstallations.installationId,
            ],
            set: {
              accountId: input.accountId,
              githubAccountId: input.githubAccountId,
              accountLogin: input.accountLogin,
              accountType: input.accountType,
              repositoryScope: "selected",
              linkedBySubjectId: input.linkedBySubjectId,
              githubActorId: input.githubActorId,
              githubActorLogin: input.githubActorLogin,
              authorityKind: input.authorityKind,
              authorityCheckedAt: input.authorityCheckedAt,
              authorityExpiresAt: input.authorityExpiresAt,
              authorityNonce: input.authorityNonce,
              updatedAt: input.authorityCheckedAt,
            },
          })
          .returning();
        if (!row) {
          throw new Error("Failed to bind GitHub installation");
        }
        await tx
          .delete(schema.githubInstallationRepositories)
          .where(
            and(
              eq(schema.githubInstallationRepositories.workspaceId, input.workspaceId),
              eq(schema.githubInstallationRepositories.installationId, input.installationId),
            ),
          );
        for (let offset = 0; offset < repositoryIds.length; offset += 1_000) {
          await tx.insert(schema.githubInstallationRepositories).values(
            repositoryIds.slice(offset, offset + 1_000).map((repositoryId) => ({
              accountId: input.accountId,
              workspaceId: input.workspaceId,
              installationId: input.installationId,
              repositoryId,
            })),
          );
        }
        // Recheck against the database clock after all writes. Throwing here
        // rolls the transaction back if the proof expired while it was being
        // committed, so no partial nonce or binding can survive.
        await assertGitHubAuthorityWindowOpen(
          tx,
          input.authorityCheckedAt,
          input.authorityExpiresAt,
        );
        return { ...mapGitHubInstallation(row), repositoryIds };
      }),
  );
}

async function assertGitHubAuthorityWindowOpen(
  tx: Database,
  checkedAt: Date,
  expiresAt: Date,
): Promise<void> {
  // postgres.js does not serialize JavaScript Date instances passed through
  // raw Drizzle SQL. Bind the already-validated ISO timestamp representation
  // and retain PostgreSQL's timestamptz/database-clock authority checks.
  const checkedAtIso = checkedAt.toISOString();
  const expiresAtIso = expiresAt.toISOString();
  const result = await tx.execute<{ valid: boolean }>(sql`
    select (
      ${checkedAtIso}::timestamptz <= clock_timestamp()
      and clock_timestamp() < ${expiresAtIso}::timestamptz
      and ${expiresAtIso}::timestamptz <= ${checkedAtIso}::timestamptz + interval '10 minutes'
    ) as valid
  `);
  if (result[0]?.valid !== true) {
    throw new GitHubInstallationAuthorityCommitError();
  }
}

export async function listGitHubInstallationsForWorkspace(
  db: Database,
  workspaceId: string,
): Promise<GitHubInstallation[]> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const rows = await scopedDb
      .select()
      .from(schema.githubInstallations)
      .where(eq(schema.githubInstallations.workspaceId, workspaceId))
      .orderBy(desc(schema.githubInstallations.updatedAt));
    return rows.map(mapGitHubInstallation);
  });
}

export async function listGitHubInstallationIdsForWorkspace(
  db: Database,
  workspaceId: string,
): Promise<number[]> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const rows = await scopedDb
      .select({ installationId: schema.githubInstallations.installationId })
      .from(schema.githubInstallations)
      .where(eq(schema.githubInstallations.workspaceId, workspaceId))
      .orderBy(desc(schema.githubInstallations.updatedAt));
    return rows.map((row) => row.installationId);
  });
}

export async function listGitHubInstallationAccessForWorkspace(
  db: Database,
  workspaceId: string,
): Promise<GitHubInstallationAccess[]> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const [installations, repositories] = await Promise.all([
      scopedDb
        .select()
        .from(schema.githubInstallations)
        .where(eq(schema.githubInstallations.workspaceId, workspaceId))
        .orderBy(desc(schema.githubInstallations.updatedAt)),
      scopedDb
        .select({
          installationId: schema.githubInstallationRepositories.installationId,
          repositoryId: schema.githubInstallationRepositories.repositoryId,
        })
        .from(schema.githubInstallationRepositories)
        .where(eq(schema.githubInstallationRepositories.workspaceId, workspaceId)),
    ]);
    const repositoriesByInstallation = new Map<number, number[]>();
    for (const repository of repositories) {
      const ids = repositoriesByInstallation.get(repository.installationId) ?? [];
      ids.push(repository.repositoryId);
      repositoriesByInstallation.set(repository.installationId, ids);
    }
    return installations.map((installation) => ({
      ...mapGitHubInstallation(installation),
      repositoryIds: repositoriesByInstallation.get(installation.installationId) ?? [],
    }));
  });
}

export async function areGitHubRepositoriesAllowedForWorkspace(
  db: Database,
  workspaceId: string,
  installationId: number,
  repositoryIds: number[],
): Promise<boolean> {
  const requestedIds = [...new Set(repositoryIds)];
  if (requestedIds.length === 0) {
    return false;
  }
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const [installation] = await scopedDb
      .select()
      .from(schema.githubInstallations)
      .where(
        and(
          eq(schema.githubInstallations.workspaceId, workspaceId),
          eq(schema.githubInstallations.installationId, installationId),
        ),
      )
      .limit(1);
    if (!installation) {
      return false;
    }
    const allowed = await scopedDb
      .select({
        repositoryId: schema.githubInstallationRepositories.repositoryId,
      })
      .from(schema.githubInstallationRepositories)
      .where(
        and(
          eq(schema.githubInstallationRepositories.workspaceId, workspaceId),
          eq(schema.githubInstallationRepositories.installationId, installationId),
          inArray(schema.githubInstallationRepositories.repositoryId, requestedIds),
        ),
      );
    if (allowed.length !== requestedIds.length) {
      return false;
    }
    return hasAuditableGitHubInstallationAuthority({
      ...mapGitHubInstallation(installation),
      repositoryIds: allowed.map((row) => row.repositoryId),
    });
  });
}

export async function deleteGitHubInstallationBinding(
  db: Database,
  input: { accountId: string; workspaceId: string; installationId: number },
): Promise<boolean> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      const rows = await scopedDb
        .delete(schema.githubInstallations)
        .where(
          and(
            eq(schema.githubInstallations.workspaceId, input.workspaceId),
            eq(schema.githubInstallations.installationId, input.installationId),
          ),
        )
        .returning({ id: schema.githubInstallations.id });
      return rows.length > 0;
    },
  );
}

export async function recordUsageEvent(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    subjectId?: string | null;
    eventType: string;
    quantity: number;
    unit: string;
    sourceResourceType?: string | null;
    sourceResourceId?: string | null;
    sessionId?: string | null;
    turnId?: string | null;
    turnAttemptId?: string | null;
    initiator?: TurnInitiator | null;
    initiatorContext?: TurnInitiatorContext;
    origin?: SessionTurnSource | null;
    idempotencyKey: string;
    occurredAt?: Date;
  },
): Promise<UsageEvent> {
  if (input.turnId && !input.sessionId) {
    throw new Error("recordUsageEvent: turnId requires sessionId");
  }
  if (input.turnAttemptId && !input.turnId) {
    throw new Error("recordUsageEvent: turnAttemptId requires turnId");
  }
  if (input.initiatorContext && !input.initiator) {
    throw new Error("recordUsageEvent: initiatorContext requires initiator");
  }
  const attribution = input.initiator
    ? initiatorColumns({
        initiator: input.initiator,
        context: input.initiatorContext ?? {},
      })
    : {
        initiatorKind: null,
        initiatorSubjectId: null,
        initiatorContext: {},
      };
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      const [row] = await scopedDb
        .insert(schema.usageEvents)
        .values({
          accountId: input.accountId,
          workspaceId: input.workspaceId,
          subjectId: input.subjectId ?? null,
          eventType: input.eventType,
          quantity: input.quantity,
          unit: input.unit,
          sourceResourceType: input.sourceResourceType ?? null,
          sourceResourceId: input.sourceResourceId ?? null,
          sessionId: input.sessionId ?? null,
          turnId: input.turnId ?? null,
          turnAttemptId: input.turnAttemptId ?? null,
          ...attribution,
          origin: input.origin ?? null,
          idempotencyKey: input.idempotencyKey,
          occurredAt: input.occurredAt ?? new Date(),
        })
        .onConflictDoUpdate({
          target: schema.usageEvents.idempotencyKey,
          set: {
            sessionId: sql`coalesce(${schema.usageEvents.sessionId}, excluded.session_id)`,
            turnId: sql`coalesce(${schema.usageEvents.turnId}, excluded.turn_id)`,
            turnAttemptId: sql`coalesce(${schema.usageEvents.turnAttemptId}, excluded.turn_attempt_id)`,
            initiatorKind: sql`coalesce(${schema.usageEvents.initiatorKind}, excluded.initiator_kind)`,
            initiatorSubjectId: sql`coalesce(${schema.usageEvents.initiatorSubjectId}, excluded.initiator_subject_id)`,
            initiatorContext: sql`case
              when ${schema.usageEvents.initiatorKind} is null then excluded.initiator_context
              else ${schema.usageEvents.initiatorContext}
            end`,
            origin: sql`coalesce(${schema.usageEvents.origin}, excluded.origin)`,
          },
        })
        .returning();
      if (row) {
        const expectedContext = [
          ["sessionId", input.sessionId, row.sessionId],
          ["turnId", input.turnId, row.turnId],
          ["turnAttemptId", input.turnAttemptId, row.turnAttemptId],
        ] as const;
        for (const [field, expected, actual] of expectedContext) {
          if (expected && actual !== expected) {
            throw new Error(`recordUsageEvent: idempotency key resolved to a different ${field}`);
          }
        }
        if (
          input.initiator &&
          (row.initiatorKind !== input.initiator.kind ||
            row.initiatorSubjectId !== input.initiator.subjectId)
        ) {
          throw new Error("recordUsageEvent: idempotency key resolved to a different initiator");
        }
        if (input.origin && row.origin !== input.origin) {
          throw new Error("recordUsageEvent: idempotency key resolved to a different origin");
        }
        return mapUsageEvent(row);
      }
      throw new Error("Failed to record usage event");
    },
  );
}

export type ModelCallBillingPath = "opengeni_credits" | "external";

export type ModelCallFact = {
  id: string;
  accountId: string;
  workspaceId: string;
  sessionId: string;
  turnId: string;
  turnAttemptId: string | null;
  sourceKey: string;
  provider: string;
  providerApi: string;
  model: string;
  billingPath: ModelCallBillingPath;
  turnSource: string | null;
  initiatorKind: string | null;
  initiatorSubjectId: string | null;
  scheduledTaskId: string | null;
  inputTokens: number | null;
  outputTokens: number | null;
  cachedTokens: number | null;
  cacheWriteTokens: number | null;
  reasoningTokens: number | null;
  totalTokens: number | null;
  pricedCostMicros: number;
  occurredAt: Date;
  recordedAt: Date;
};

function mapModelCallFact(row: typeof schema.modelCallFacts.$inferSelect): ModelCallFact {
  const billingPath = row.billingPath;
  if (billingPath !== "opengeni_credits" && billingPath !== "external") {
    throw new Error(`model_call_facts: invalid billing_path ${billingPath}`);
  }
  return {
    id: row.id,
    accountId: row.accountId,
    workspaceId: row.workspaceId,
    sessionId: row.sessionId,
    turnId: row.turnId,
    turnAttemptId: row.turnAttemptId,
    sourceKey: row.sourceKey,
    provider: row.provider,
    providerApi: row.providerApi,
    model: row.model,
    billingPath,
    turnSource: row.turnSource,
    initiatorKind: row.initiatorKind,
    initiatorSubjectId: row.initiatorSubjectId,
    scheduledTaskId: row.scheduledTaskId,
    inputTokens: row.inputTokens,
    outputTokens: row.outputTokens,
    cachedTokens: row.cachedTokens,
    cacheWriteTokens: row.cacheWriteTokens,
    reasoningTokens: row.reasoningTokens,
    totalTokens: row.totalTokens,
    pricedCostMicros: row.pricedCostMicros,
    occurredAt: row.occurredAt,
    recordedAt: row.recordedAt,
  };
}

function scheduledRunIdsFromContext(context: unknown): string[] {
  if (!context || typeof context !== "object" || Array.isArray(context)) return [];
  const raw = (context as Record<string, unknown>).scheduledRunIds;
  if (!Array.isArray(raw)) return [];
  return raw.filter((value): value is string => typeof value === "string" && value.length > 0);
}

async function resolveScheduledTaskIdForTurn(
  scopedDb: Database,
  input: {
    workspaceId: string;
    initiatorSubjectId: string | null;
    initiatorContext: unknown;
  },
): Promise<string | null> {
  // initiatorSubjectId is intentionally unused: any turn that carries
  // scheduledRunIds is eligible for schedule attribution (scheduler wakes and
  // inherited contexts alike). Mis-bucketing by turn.source remains forbidden.
  void input.initiatorSubjectId;
  const runIds = scheduledRunIdsFromContext(input.initiatorContext);
  if (runIds.length === 0) return null;
  // Prefer the earliest run when a batch somehow carries multiple ids so
  // attribution is deterministic across retries.
  const [run] = await scopedDb
    .select({ taskId: schema.scheduledTaskRuns.taskId })
    .from(schema.scheduledTaskRuns)
    .where(
      and(
        eq(schema.scheduledTaskRuns.workspaceId, input.workspaceId),
        inArray(schema.scheduledTaskRuns.id, runIds),
      ),
    )
    .orderBy(schema.scheduledTaskRuns.createdAt)
    .limit(1);
  return run?.taskId ?? null;
}

/**
 * Idempotent Insights fact for one authoritative model call. Soft-callers must
 * never let failures affect billing; this writer itself is safe to retry.
 */
export async function recordModelCallFact(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sessionId: string;
    turnId: string;
    turnAttemptId?: string | null;
    sourceKey: string;
    provider: string;
    providerApi: string;
    model: string;
    billingPath: ModelCallBillingPath;
    pricedCostMicros: number;
    inputTokens?: number | null;
    outputTokens?: number | null;
    cachedTokens?: number | null;
    cacheWriteTokens?: number | null;
    reasoningTokens?: number | null;
    totalTokens?: number | null;
    occurredAt?: Date;
  },
): Promise<ModelCallFact> {
  if (input.pricedCostMicros < 0 || !Number.isSafeInteger(input.pricedCostMicros)) {
    throw new Error("recordModelCallFact: pricedCostMicros must be a non-negative safe integer");
  }
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      const [turn] = await scopedDb
        .select({
          source: schema.sessionTurns.source,
          initiatorKind: schema.sessionTurns.initiatorKind,
          initiatorSubjectId: schema.sessionTurns.initiatorSubjectId,
          initiatorContext: schema.sessionTurns.initiatorContext,
        })
        .from(schema.sessionTurns)
        .where(
          and(
            eq(schema.sessionTurns.workspaceId, input.workspaceId),
            eq(schema.sessionTurns.id, input.turnId),
          ),
        )
        .limit(1);
      const scheduledTaskId = turn
        ? await resolveScheduledTaskIdForTurn(scopedDb, {
            workspaceId: input.workspaceId,
            initiatorSubjectId: turn.initiatorSubjectId,
            initiatorContext: turn.initiatorContext,
          })
        : null;
      const occurredAt = input.occurredAt ?? new Date();
      const [row] = await scopedDb
        .insert(schema.modelCallFacts)
        .values({
          accountId: input.accountId,
          workspaceId: input.workspaceId,
          sessionId: input.sessionId,
          turnId: input.turnId,
          turnAttemptId: input.turnAttemptId ?? null,
          sourceKey: input.sourceKey,
          provider: input.provider,
          providerApi: input.providerApi,
          model: input.model,
          billingPath: input.billingPath,
          turnSource: turn?.source ?? null,
          initiatorKind: turn?.initiatorKind ?? null,
          initiatorSubjectId: turn?.initiatorSubjectId ?? null,
          scheduledTaskId,
          inputTokens: input.inputTokens ?? null,
          outputTokens: input.outputTokens ?? null,
          cachedTokens: input.cachedTokens ?? null,
          cacheWriteTokens: input.cacheWriteTokens ?? null,
          reasoningTokens: input.reasoningTokens ?? null,
          totalTokens: input.totalTokens ?? null,
          pricedCostMicros: input.pricedCostMicros,
          occurredAt,
        })
        .onConflictDoUpdate({
          target: [
            schema.modelCallFacts.workspaceId,
            schema.modelCallFacts.turnId,
            schema.modelCallFacts.sourceKey,
          ],
          set: {
            turnAttemptId: sql`coalesce(${schema.modelCallFacts.turnAttemptId}, excluded.turn_attempt_id)`,
            scheduledTaskId: sql`coalesce(${schema.modelCallFacts.scheduledTaskId}, excluded.scheduled_task_id)`,
            initiatorKind: sql`coalesce(${schema.modelCallFacts.initiatorKind}, excluded.initiator_kind)`,
            initiatorSubjectId: sql`coalesce(${schema.modelCallFacts.initiatorSubjectId}, excluded.initiator_subject_id)`,
            turnSource: sql`coalesce(${schema.modelCallFacts.turnSource}, excluded.turn_source)`,
          },
        })
        .returning();
      if (!row) {
        throw new Error("Failed to record model call fact");
      }
      return mapModelCallFact(row);
    },
  );
}

export async function listUsageEvents(
  db: Database,
  input: {
    accountId: string;
    workspaceId?: string;
    limit?: number;
  },
): Promise<UsageEvent[]> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId ?? null },
    async (scopedDb) => {
      const rows = await scopedDb
        .select()
        .from(schema.usageEvents)
        .where(
          input.workspaceId
            ? and(
                eq(schema.usageEvents.accountId, input.accountId),
                eq(schema.usageEvents.workspaceId, input.workspaceId),
              )
            : eq(schema.usageEvents.accountId, input.accountId),
        )
        .orderBy(desc(schema.usageEvents.occurredAt), desc(schema.usageEvents.recordedAt))
        .limit(input.limit ?? 100);
      return rows.map(mapUsageEvent);
    },
  );
}

export async function sumUsageQuantity(
  db: Database,
  input: {
    accountId?: string;
    workspaceId?: string;
    eventType: string;
    since?: Date;
  },
): Promise<number> {
  const context = input.workspaceId
    ? await rlsContextForWorkspace(db, input.workspaceId)
    : input.accountId
      ? { accountId: input.accountId, workspaceId: null }
      : null;
  if (!context) {
    throw new Error("Usage quantity queries require accountId or workspaceId");
  }
  return await withRlsContext(db, context, async (scopedDb) => {
    const clauses = [
      eq(schema.usageEvents.eventType, input.eventType),
      ...(input.accountId ? [eq(schema.usageEvents.accountId, input.accountId)] : []),
      ...(input.workspaceId ? [eq(schema.usageEvents.workspaceId, input.workspaceId)] : []),
      ...(input.since ? [gt(schema.usageEvents.occurredAt, input.since)] : []),
    ];
    const [{ total } = { total: 0 }] = await scopedDb
      .select({
        total: sql<number>`coalesce(sum(${schema.usageEvents.quantity}), 0)`,
      })
      .from(schema.usageEvents)
      .where(and(...clauses));
    return Number(total);
  });
}

export async function applyCreditLedgerEntry(
  db: Database,
  input: {
    accountId: string;
    workspaceId?: string | null;
    type: string;
    amountMicros: number;
    sourceType?: string | null;
    sourceId?: string | null;
    idempotencyKey: string;
    metadata?: Record<string, unknown>;
    occurredAt?: Date;
  },
): Promise<BillingBalance> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId ?? null },
    async (scopedDb) => {
      await scopedDb
        .insert(schema.creditLedgerEntries)
        .values({
          accountId: input.accountId,
          workspaceId: input.workspaceId ?? null,
          type: input.type,
          amountMicros: input.amountMicros,
          sourceType: input.sourceType ?? null,
          sourceId: input.sourceId ?? null,
          idempotencyKey: input.idempotencyKey,
          metadata: input.metadata ?? {},
          occurredAt: input.occurredAt ?? new Date(),
        })
        .onConflictDoNothing({
          target: schema.creditLedgerEntries.idempotencyKey,
        });
      return await getBillingBalance(scopedDb, input.accountId);
    },
  );
}

export async function applyCreditDebitUpToBalance(
  db: Database,
  input: {
    accountId: string;
    workspaceId?: string | null;
    type: string;
    requestedAmountMicros: number;
    sourceType?: string | null;
    sourceId?: string | null;
    idempotencyKey: string;
    metadata?: Record<string, unknown>;
    occurredAt?: Date;
  },
): Promise<{ balance: BillingBalance; debitedMicros: number }> {
  if (input.requestedAmountMicros <= 0) {
    return {
      balance: await getBillingBalance(db, input.accountId),
      debitedMicros: 0,
    };
  }
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId ?? null },
    async (scopedDb) => {
      await scopedDb.execute(sql`select pg_advisory_xact_lock(hashtext(${input.accountId}))`);
      const before = await getBillingBalance(scopedDb, input.accountId);
      const candidateDebitMicros = Math.min(
        input.requestedAmountMicros,
        Math.max(0, before.balanceMicros),
      );
      let debitedMicros = 0;
      if (candidateDebitMicros > 0) {
        const inserted = await scopedDb
          .insert(schema.creditLedgerEntries)
          .values({
            accountId: input.accountId,
            workspaceId: input.workspaceId ?? null,
            type: input.type,
            amountMicros: -candidateDebitMicros,
            sourceType: input.sourceType ?? null,
            sourceId: input.sourceId ?? null,
            idempotencyKey: input.idempotencyKey,
            metadata: {
              ...input.metadata,
              requestedAmountMicros: input.requestedAmountMicros,
              debitedMicros: candidateDebitMicros,
            },
            occurredAt: input.occurredAt ?? new Date(),
          })
          .onConflictDoNothing({
            target: schema.creditLedgerEntries.idempotencyKey,
          })
          .returning({ id: schema.creditLedgerEntries.id });
        debitedMicros = inserted.length === 1 ? candidateDebitMicros : 0;
      }
      return {
        balance: await getBillingBalance(scopedDb, input.accountId),
        debitedMicros,
      };
    },
  );
}

export async function hasCreditLedgerEntry(
  db: Database,
  accountId: string,
  idempotencyKey: string,
): Promise<boolean> {
  return await withAccountRls(db, accountId, async (scopedDb) => {
    const [row] = await scopedDb
      .select({ id: schema.creditLedgerEntries.id })
      .from(schema.creditLedgerEntries)
      .where(
        and(
          eq(schema.creditLedgerEntries.accountId, accountId),
          eq(schema.creditLedgerEntries.idempotencyKey, idempotencyKey),
        ),
      )
      .limit(1);
    return Boolean(row);
  });
}

export async function getBillingCustomer(
  db: Database,
  accountId: string,
  provider = "stripe",
): Promise<{
  accountId: string;
  provider: string;
  providerCustomerId: string;
  email: string | null;
} | null> {
  return await withAccountRls(db, accountId, async (scopedDb) => {
    const [row] = await scopedDb
      .select()
      .from(schema.billingCustomers)
      .where(
        and(
          eq(schema.billingCustomers.accountId, accountId),
          eq(schema.billingCustomers.provider, provider),
        ),
      )
      .limit(1);
    return row
      ? {
          accountId: row.accountId,
          provider: row.provider,
          providerCustomerId: row.providerCustomerId,
          email: row.email,
        }
      : null;
  });
}

export async function upsertBillingCustomer(
  db: Database,
  input: {
    accountId: string;
    provider?: string;
    providerCustomerId: string;
    email?: string | null;
  },
): Promise<void> {
  await withAccountRls(db, input.accountId, async (scopedDb) => {
    await scopedDb
      .insert(schema.billingCustomers)
      .values({
        accountId: input.accountId,
        provider: input.provider ?? "stripe",
        providerCustomerId: input.providerCustomerId,
        email: input.email ?? null,
      })
      .onConflictDoUpdate({
        target: [schema.billingCustomers.accountId, schema.billingCustomers.provider],
        set: {
          providerCustomerId: input.providerCustomerId,
          email: input.email ?? null,
          updatedAt: new Date(),
        },
      });
  });
}

