export async function listSessionHumanInputRequests(
  db: Database,
  workspaceId: string,
  sessionId: string,
  options: { status?: SessionHumanInputRequest["status"]; limit?: number } = {},
): Promise<SessionHumanInputRequest[]> {
  const limit = Math.min(100, Math.max(1, Math.floor(options.limit ?? 50)));
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const predicates = [
      eq(schema.sessionHumanInputRequests.workspaceId, workspaceId),
      eq(schema.sessionHumanInputRequests.sessionId, sessionId),
    ];
    if (options.status) {
      predicates.push(eq(schema.sessionHumanInputRequests.status, options.status));
    }
    const rows = await scopedDb
      .select()
      .from(schema.sessionHumanInputRequests)
      .where(and(...predicates))
      .orderBy(
        desc(schema.sessionHumanInputRequests.createdAt),
        desc(schema.sessionHumanInputRequests.id),
      )
      .limit(limit);
    return rows.map(mapSessionHumanInputRequest);
  });
}

function validateAnsweredHumanInput(
  questions: HumanInputQuestion[],
  answers: HumanInputAnswer[],
): HumanInputAnswer[] {
  const questionsById = new Map(questions.map((question) => [question.id, question]));
  const answersById = new Map<string, HumanInputAnswer>();
  for (const answer of answers) {
    if (!questionsById.has(answer.questionId)) {
      throw new HumanInputResponseValidationError(
        "INVALID_RESPONSE",
        `Unknown human-input question: ${answer.questionId}`,
      );
    }
    if (answersById.has(answer.questionId)) {
      throw new HumanInputResponseValidationError(
        "INVALID_RESPONSE",
        `Duplicate human-input answer: ${answer.questionId}`,
      );
    }
    answersById.set(answer.questionId, answer);
  }
  for (const question of questions) {
    const answer = answersById.get(question.id);
    const values = answer?.values ?? [];
    const other = answer?.other?.trim() ?? "";
    const suppliedCount = values.length + (other ? 1 : 0);
    if (question.required && suppliedCount === 0) {
      throw new HumanInputResponseValidationError(
        "INVALID_RESPONSE",
        `Question ${question.id} requires an answer`,
      );
    }
    if (!answer) continue;
    if (new Set(values).size !== values.length) {
      throw new HumanInputResponseValidationError(
        "INVALID_RESPONSE",
        `Question ${question.id} contains duplicate values`,
      );
    }
    if (question.kind === "text") {
      if (values.length > 1 || other) {
        throw new HumanInputResponseValidationError(
          "INVALID_RESPONSE",
          `Text question ${question.id} accepts one value`,
        );
      }
      const value = values[0] ?? "";
      const minLength = question.validation?.minLength;
      const maxLength = question.validation?.maxLength;
      if (minLength != null && value.length < minLength) {
        throw new HumanInputResponseValidationError(
          "INVALID_RESPONSE",
          `Question ${question.id} is shorter than its minimum length`,
        );
      }
      if (maxLength != null && value.length > maxLength) {
        throw new HumanInputResponseValidationError(
          "INVALID_RESPONSE",
          `Question ${question.id} exceeds its maximum length`,
        );
      }
      continue;
    }
    if (other && !question.allowOther) {
      throw new HumanInputResponseValidationError(
        "INVALID_RESPONSE",
        `Question ${question.id} does not allow Other`,
      );
    }
    const optionIds = new Set(question.options.map((option) => option.id));
    if (values.some((value) => !optionIds.has(value))) {
      throw new HumanInputResponseValidationError(
        "INVALID_RESPONSE",
        `Question ${question.id} contains an unknown option`,
      );
    }
    if (question.kind === "single_select" && suppliedCount > 1) {
      throw new HumanInputResponseValidationError(
        "INVALID_RESPONSE",
        `Single-select question ${question.id} accepts one selection`,
      );
    }
    if (question.kind === "multi_select") {
      const minSelections = question.validation?.minSelections;
      const maxSelections = question.validation?.maxSelections;
      if (minSelections != null && suppliedCount < minSelections) {
        throw new HumanInputResponseValidationError(
          "INVALID_RESPONSE",
          `Question ${question.id} has too few selections`,
        );
      }
      if (maxSelections != null && suppliedCount > maxSelections) {
        throw new HumanInputResponseValidationError(
          "INVALID_RESPONSE",
          `Question ${question.id} has too many selections`,
        );
      }
    }
  }
  return answers;
}

export function validateHumanInputResponse(
  request: Pick<SessionHumanInputRequest, "questions" | "allowSkip">,
  rawResponse: unknown,
): HumanInputResponse {
  const response = SubmitHumanInputResponseRequest.parse(rawResponse);
  if (response.outcome === "skipped") {
    if (!request.allowSkip) {
      throw new HumanInputResponseValidationError(
        "SKIP_NOT_ALLOWED",
        "This human-input request cannot be skipped",
      );
    }
    return response;
  }
  return {
    outcome: "answered",
    answers: validateAnsweredHumanInput(request.questions, response.answers),
  };
}

export type AcceptSessionHumanInputResponseResult =
  | {
      action: "accepted";
      request: SessionHumanInputRequest;
      event: SessionEvent;
      events: SessionEvent[];
      workflowWakeRevision: number;
    }
  | {
      action: "conflict";
      request: SessionHumanInputRequest;
      events: SessionEvent[];
      workflowWakeRevision: number | null;
    }
  | { action: "not_found" };

/**
 * One requires-action boundary may admit exactly one durable resume event.
 * Human-input responses and ordinary approval decisions share this gate: a
 * mixed parallel interruption batch must not accept one of each before the
 * workflow claims the first and advances the turn's trigger/generation.
 */
async function hasAcceptedRequiresActionAdvance(
  tx: Database,
  input: {
    workspaceId: string;
    sessionId: string;
    turnId: string;
    turnGeneration: number;
    triggerEventId: string;
  },
): Promise<boolean> {
  const [trigger] = await tx
    .select({ sequence: schema.sessionEvents.sequence })
    .from(schema.sessionEvents)
    .where(
      and(
        eq(schema.sessionEvents.workspaceId, input.workspaceId),
        eq(schema.sessionEvents.sessionId, input.sessionId),
        eq(schema.sessionEvents.id, input.triggerEventId),
      ),
    )
    .limit(1);
  if (!trigger) throw new Error(`Turn trigger not found: ${input.triggerEventId}`);
  const [accepted] = await tx
    .select({ id: schema.sessionEvents.id })
    .from(schema.sessionEvents)
    .where(
      and(
        eq(schema.sessionEvents.workspaceId, input.workspaceId),
        eq(schema.sessionEvents.sessionId, input.sessionId),
        eq(schema.sessionEvents.turnId, input.turnId),
        eq(schema.sessionEvents.turnGeneration, input.turnGeneration),
        inArray(schema.sessionEvents.type, ["user.approvalDecision", "user.humanInputResponse"]),
        gt(schema.sessionEvents.sequence, trigger.sequence),
      ),
    )
    .limit(1);
  return accepted !== undefined;
}

/**
 * First-writer-wins settlement for one pending structured input boundary.
 * Session + logical turn + current freeze generation are locked with the row;
 * the creation attempt is provenance and is intentionally not the resume owner.
 */
export async function acceptSessionHumanInputResponse(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sessionId: string;
    requestId: string;
    response: unknown;
    respondedBy: string;
    clientEventId?: string | null;
    expireOnly?: boolean;
  },
): Promise<AcceptSessionHumanInputResponseResult> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (tx) => {
        const locks = await lockSessionEventWriteRows(tx as unknown as Database, {
          workspaceId: input.workspaceId,
          controlLock: "none",
          sessionIds: [input.sessionId],
        });
        const session = locks.sessions[0];
        if (!session) return { action: "not_found" } as const;
        const [request] = await tx
          .select()
          .from(schema.sessionHumanInputRequests)
          .where(
            and(
              eq(schema.sessionHumanInputRequests.workspaceId, input.workspaceId),
              eq(schema.sessionHumanInputRequests.sessionId, input.sessionId),
              eq(schema.sessionHumanInputRequests.id, input.requestId),
            ),
          )
          .for("update")
          .limit(1);
        if (!request) return { action: "not_found" } as const;
        if (input.clientEventId) {
          const [existing] = await tx
            .select()
            .from(schema.sessionEvents)
            .where(
              and(
                eq(schema.sessionEvents.workspaceId, input.workspaceId),
                eq(schema.sessionEvents.sessionId, input.sessionId),
                eq(schema.sessionEvents.clientEventId, input.clientEventId),
              ),
            )
            .limit(1);
          if (existing) {
            if (
              existing.type !== "user.humanInputResponse" ||
              (existing.payload as { requestId?: unknown }).requestId !== request.id
            ) {
              throw new Error("clientEventId belongs to a different session operation");
            }
            const workflowWakeRevision = await enqueueSessionWorkflowWakeInTransaction(
              tx as unknown as Database,
              {
                accountId: session.accountId,
                workspaceId: input.workspaceId,
                sessionId: session.id,
                temporalWorkflowId: session.temporalWorkflowId ?? `session-${session.id}`,
                reason: "approval_decision",
              },
            );
            return {
              action: "accepted",
              request: mapSessionHumanInputRequest(request),
              event: mapEvent(existing),
              events: [],
              workflowWakeRevision,
            } as const;
          }
        }
        const [turnPreview] = session.activeTurnId
          ? await tx
              .select()
              .from(schema.sessionTurns)
              .where(
                and(
                  eq(schema.sessionTurns.workspaceId, input.workspaceId),
                  eq(schema.sessionTurns.sessionId, input.sessionId),
                  eq(schema.sessionTurns.id, session.activeTurnId),
                ),
              )
              .limit(1)
          : [];
        const turn = turnPreview
          ? (
              await lockSessionEventWriteRows(tx as unknown as Database, {
                workspaceId: input.workspaceId,
                controlLock: "already_locked",
                workspaceLock: "already_locked",
                turnIds: [turnPreview.id],
              })
            ).turns[0]
          : undefined;
        const boundaryOwnsRequest =
          session.status === "requires_action" &&
          turn?.status === "requires_action" &&
          turn.id === request.turnId &&
          turn.executionGeneration === request.turnGeneration;
        if (request.status !== "pending" || !boundaryOwnsRequest) {
          return {
            action: "conflict",
            request: mapSessionHumanInputRequest(request),
            events: [],
            workflowWakeRevision: null,
          } as const;
        }
        if (
          await hasAcceptedRequiresActionAdvance(tx as unknown as Database, {
            workspaceId: input.workspaceId,
            sessionId: input.sessionId,
            turnId: turn.id,
            turnGeneration: turn.executionGeneration,
            triggerEventId: turn.triggerEventId,
          })
        ) {
          return {
            action: "conflict",
            request: mapSessionHumanInputRequest(request),
            events: [],
            workflowWakeRevision: null,
          } as const;
        }
        const now = new Date();
        const expired = request.expiresAt !== null && request.expiresAt.getTime() <= now.getTime();
        if (input.expireOnly && !expired) {
          return {
            action: "conflict",
            request: mapSessionHumanInputRequest(request),
            events: [],
            workflowWakeRevision: null,
          } as const;
        }
        const response: HumanInputResponse = expired
          ? { outcome: "expired" }
          : validateHumanInputResponse(mapSessionHumanInputRequest(request), input.response);
        const [updated] = await tx
          .update(schema.sessionHumanInputRequests)
          .set({
            status: response.outcome,
            response,
            respondedBy: expired ? "system:expired" : input.respondedBy,
            respondedAt: now,
            updatedAt: now,
          })
          .where(
            and(
              eq(schema.sessionHumanInputRequests.id, request.id),
              eq(schema.sessionHumanInputRequests.status, "pending"),
              eq(schema.sessionHumanInputRequests.turnGeneration, turn.executionGeneration),
            ),
          )
          .returning();
        if (!updated) {
          return {
            action: "conflict",
            request: mapSessionHumanInputRequest(request),
            events: [],
            workflowWakeRevision: null,
          } as const;
        }
        const [event] = await tx
          .insert(schema.sessionEvents)
          .values({
            accountId: session.accountId,
            workspaceId: input.workspaceId,
            sessionId: input.sessionId,
            turnId: turn.id,
            turnGeneration: turn.executionGeneration,
            turnAssociation: "current",
            sequence: session.lastSequence + 1,
            type: "user.humanInputResponse",
            payload: sanitizeEventPayload({ requestId: request.id, response }),
            clientEventId: expired ? null : (input.clientEventId ?? null),
            occurredAt: now,
          })
          .returning();
        if (!event) throw new Error("Failed to append human-input response");
        await tx
          .update(schema.sessions)
          .set({ lastSequence: session.lastSequence + 1, updatedAt: now })
          .where(eq(schema.sessions.id, session.id));
        const workflowWakeRevision = await enqueueSessionWorkflowWakeInTransaction(
          tx as unknown as Database,
          {
            accountId: session.accountId,
            workspaceId: input.workspaceId,
            sessionId: session.id,
            temporalWorkflowId: session.temporalWorkflowId ?? `session-${session.id}`,
            reason: "approval_decision",
          },
        );
        const mappedEvent = mapEvent(event);
        const result = {
          request: mapSessionHumanInputRequest(updated),
          events: [mappedEvent],
          workflowWakeRevision,
        };
        return expired
          ? ({ action: "conflict", ...result } as const)
          : ({ action: "accepted", event: mappedEvent, ...result } as const);
      }),
  );
}

export async function expireSessionHumanInputRequest(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sessionId: string;
    requestId: string;
  },
): Promise<AcceptSessionHumanInputResponseResult> {
  return await acceptSessionHumanInputResponse(db, {
    ...input,
    response: { outcome: "skipped" },
    respondedBy: "system:expired",
    expireOnly: true,
  });
}

export async function getHumanInputResumeForEvent(
  db: Database,
  workspaceId: string,
  sessionId: string,
  event: Pick<SessionEvent, "type" | "payload">,
): Promise<{
  requestId: string;
  toolCallId: string;
  response: HumanInputResponse;
} | null> {
  if (event.type !== "user.humanInputResponse") return null;
  const requestId = (event.payload as { requestId?: unknown }).requestId;
  if (typeof requestId !== "string") return null;
  const request = await getSessionHumanInputRequest(db, workspaceId, sessionId, requestId);
  return request?.response
    ? {
        requestId: request.id,
        toolCallId: request.toolCallId,
        response: request.response,
      }
    : null;
}

export type TurnAttemptFenceRejectReason =
  | "workspace_paused"
  | "session_paused"
  | "pending_control"
  | "active_turn_changed"
  | "generation_changed"
  | "attempt_changed"
  | "turn_terminal"
  | "not_found";

type TurnAttemptFenceResult =
  | {
      allowed: true;
      workspace: typeof schema.workspaces.$inferSelect;
      session: typeof schema.sessions.$inferSelect;
      turn: typeof schema.sessionTurns.$inferSelect;
      attempt: typeof schema.sessionTurnAttempts.$inferSelect;
    }
  | {
      allowed: false;
      reason: TurnAttemptFenceRejectReason;
      workspace: typeof schema.workspaces.$inferSelect | null;
      session: typeof schema.sessions.$inferSelect | null;
      turn: typeof schema.sessionTurns.$inferSelect | null;
      attempt: typeof schema.sessionTurnAttempts.$inferSelect | null;
    };

/**
 * Lock order for every activity write fence: workspace control -> actual
 * workspace -> session -> exact turn -> exact attempt.
 *
 * Activity writes only need a shared workspace admission lock: concurrent
 * sessions may write independently, while an exclusive workspace Pause/Resume
 * still waits for every admitted write and prevents later writes from crossing
 * the control boundary. Using FOR UPDATE here serialized every active session in
 * one workspace behind a single row and turned streaming into a workspace-wide
 * lock queue.
 */
async function lockTurnAttemptWriteFenceTx(
  tx: Database,
  input: {
    workspaceId: string;
    sessionId: string;
    turnId: string;
    executionGeneration: number;
    attemptId: string;
  },
): Promise<TurnAttemptFenceResult> {
  const locks = await lockSessionEventWriteRows(tx, {
    workspaceId: input.workspaceId,
    controlLock: "share",
    sessionIds: [input.sessionId],
    turnIds: [input.turnId],
    attemptIds: [input.attemptId],
  });
  const workspace = locks.workspace;
  const session = locks.sessions.find((row) => row.id === input.sessionId) ?? null;
  const turn = locks.turns.find((row) => row.id === input.turnId) ?? null;
  const attempt = locks.attempts.find((row) => row.id === input.attemptId) ?? null;
  const base = { workspace, session, turn, attempt };
  if (!workspace || !session || !turn || !attempt) {
    return { allowed: false, reason: "not_found", ...base };
  }
  const effectiveControl = await evaluateSessionControl(tx, input.workspaceId, input.sessionId, {
    workspaceControl: locks.control ?? undefined,
  });
  if (effectiveControl.state === "paused") {
    return {
      allowed: false,
      reason:
        effectiveControl.primaryBlocker?.kind === "workspace"
          ? "workspace_paused"
          : "session_paused",
      ...base,
    };
  }
  if (session.activeTurnId !== input.turnId) {
    return { allowed: false, reason: "active_turn_changed", ...base };
  }
  if (turn.executionGeneration !== input.executionGeneration) {
    return { allowed: false, reason: "generation_changed", ...base };
  }
  if (turn.activeAttemptId !== input.attemptId) {
    return { allowed: false, reason: "attempt_changed", ...base };
  }
  if (
    turn.accountId !== session.accountId ||
    turn.sessionId !== input.sessionId ||
    attempt.accountId !== session.accountId ||
    attempt.sessionId !== input.sessionId ||
    attempt.turnId !== input.turnId ||
    attempt.executionGeneration !== input.executionGeneration ||
    !["claimed", "running"].includes(attempt.state)
  ) {
    return { allowed: false, reason: "attempt_changed", ...base };
  }
  const [interruption] = await tx
    .select({ id: schema.sessionAttemptInterruptions.id })
    .from(schema.sessionAttemptInterruptions)
    .where(
      and(
        eq(schema.sessionAttemptInterruptions.workspaceId, input.workspaceId),
        eq(schema.sessionAttemptInterruptions.sessionId, input.sessionId),
        eq(schema.sessionAttemptInterruptions.attemptId, input.attemptId),
        inArray(schema.sessionAttemptInterruptions.state, ["pending", "delivered", "acknowledged"]),
      ),
    )
    .limit(1);
  if (interruption) {
    return { allowed: false, reason: "pending_control", ...base };
  }
  if (!["running", "requires_action"].includes(turn.status)) {
    return { allowed: false, reason: "turn_terminal", ...base };
  }
  return { allowed: true, workspace, session, turn, attempt };
}

export type InstallOrReadTurnExecutionPolicyForAttemptResult =
  | {
      accepted: true;
      installed: boolean;
      policy: TurnExecutionPolicyV1;
      turn: SessionTurn;
    }
  | {
      accepted: false;
      reason: TurnAttemptFenceRejectReason;
    };

/**
 * Freeze a legacy turn's execution identity at its first admitted attempt, or
 * return the policy already accepted for this logical turn. The exact active
 * attempt owns this mutation; malformed present metadata fails closed and a
 * replay never replaces an existing valid policy.
 */
export async function installOrReadTurnExecutionPolicyForAttempt(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sessionId: string;
    turnId: string;
    executionGeneration: number;
    attemptId: string;
    policyForAbsent: TurnExecutionPolicyV1;
  },
): Promise<InstallOrReadTurnExecutionPolicyForAttemptResult> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (tx) => {
        const fence = await lockTurnAttemptWriteFenceTx(tx, {
          workspaceId: input.workspaceId,
          sessionId: input.sessionId,
          turnId: input.turnId,
          executionGeneration: input.executionGeneration,
          attemptId: input.attemptId,
        });
        if (!fence.allowed) {
          return { accepted: false as const, reason: fence.reason };
        }

        const existing = readTurnExecutionPolicyV1(fence.turn.metadata);
        if (existing.kind === "valid") {
          return {
            accepted: true as const,
            installed: false,
            policy: existing.policy,
            turn: mapSessionTurn(fence.turn),
          };
        }

        const policy = TurnExecutionPolicyV1.parse(input.policyForAbsent);
        const [updated] = await tx
          .update(schema.sessionTurns)
          .set({
            metadata: metadataWithTurnExecutionPolicyV1(fence.turn.metadata, policy),
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(schema.sessionTurns.workspaceId, input.workspaceId),
              eq(schema.sessionTurns.sessionId, input.sessionId),
              eq(schema.sessionTurns.id, input.turnId),
              eq(schema.sessionTurns.status, "running"),
              eq(schema.sessionTurns.executionGeneration, input.executionGeneration),
              eq(schema.sessionTurns.activeAttemptId, input.attemptId),
            ),
          )
          .returning();
        if (!updated) {
          throw new Error("Turn execution policy owner changed while its row was locked");
        }
        return {
          accepted: true as const,
          installed: true,
          policy,
          turn: mapSessionTurn(updated),
        };
      }),
  );
}

/**
 * Append conversation items (verbatim SDK AgentInputItems) to the session's
 * history. Idempotent on (workspace, session, position): concurrent or
 * repeated writers (streaming writes + turn-end reconciliation) converge
 * instead of duplicating.
 */
export async function appendSessionHistoryItems(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sessionId: string;
    turnId: string;
    expectedExecutionGeneration: number;
    expectedAttemptId: string;
    // The codex account that produced these items (the turn's resolved credential
    // id), or null/undefined on the non-codex path. Stored verbatim so the read
    // path can strip cross-account reasoning.encrypted_content blobs per turn.
    producerCodexCredentialId?: string | null;
    modelToolOutputTruncationTokens?: number;
    items: Array<{ position: number; item: Record<string, unknown> }>;
  },
): Promise<boolean> {
  if (input.items.length === 0) {
    return true;
  }
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      return await scopedDb.transaction(async (tx) => {
        const allowed = await lockTurnAttemptWriteFenceTx(tx, {
          workspaceId: input.workspaceId,
          sessionId: input.sessionId,
          turnId: input.turnId,
          executionGeneration: input.expectedExecutionGeneration,
          attemptId: input.expectedAttemptId,
        });
        if (!allowed.allowed) return false;
        await tx
          .insert(schema.sessionHistoryItems)
          .values(
            input.items.map((entry) => ({
              accountId: input.accountId,
              workspaceId: input.workspaceId,
              sessionId: input.sessionId,
              turnId: input.turnId,
              producerCodexCredentialId: input.producerCodexCredentialId ?? null,
              position: entry.position,
              // This is the canonical model-memory boundary. The pending-call
              // ledger and audit event may retain their separate raw/preview
              // forms, but conversation truth is always the bounded Codex form.
              item: sanitizeModelPayload(
                boundModelToolOutputItem(entry.item, input.modelToolOutputTruncationTokens),
              ),
            })),
          )
          .onConflictDoNothing({
            target: [
              schema.sessionHistoryItems.workspaceId,
              schema.sessionHistoryItems.sessionId,
              schema.sessionHistoryItems.position,
            ],
          });
        return true;
      });
    },
  );
}

export type PendingSessionToolCallInput = {
  accountId: string;
  workspaceId: string;
  sessionId: string;
  turnId: string;
  executionGeneration: number;
  attemptId: string;
  callId: string;
  callType: string;
  callItem: Record<string, unknown>;
  modelToolOutputTruncationTokens?: number;
};

function assertPendingToolOutputPolicyMatches(
  stored: number | null,
  supplied: number | undefined,
  callId: string,
): void {
  if (stored !== null && supplied !== undefined && stored !== supplied) {
    throw new Error(
      `SDK tool call ${callId} changed model tool-output policy from ${stored} to ${supplied}`,
    );
  }
}

/**
 * Durably capture the raw SDK call item at the exact attempt boundary. This is
 * model-facing truth, deliberately separate from the redacted session-event
 * projection. The receipt belongs to the logical turn so an approval resume can
 * settle it from a newer attempt. Duplicate SDK delivery converges on the
 * unique (turn, call) identity.
 */
export async function registerPendingSessionToolCall(
  db: Database,
  input: PendingSessionToolCallInput,
): Promise<{ accepted: boolean; registered: boolean }> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (tx) => {
        const fence = await lockTurnAttemptWriteFenceTx(tx, {
          workspaceId: input.workspaceId,
          sessionId: input.sessionId,
          turnId: input.turnId,
          executionGeneration: input.executionGeneration,
          attemptId: input.attemptId,
        });
        if (!fence.allowed) return { accepted: false, registered: false };
        const inserted = await tx
          .insert(schema.sessionPendingToolCalls)
          .values({
            accountId: input.accountId,
            workspaceId: input.workspaceId,
            sessionId: input.sessionId,
            turnId: input.turnId,
            executionGeneration: input.executionGeneration,
            attemptId: input.attemptId,
            callId: input.callId,
            callType: input.callType,
            callItem: sanitizeModelPayload(input.callItem),
            modelToolOutputTruncationTokens: input.modelToolOutputTruncationTokens ?? null,
          })
          .onConflictDoNothing({
            target: [
              schema.sessionPendingToolCalls.workspaceId,
              schema.sessionPendingToolCalls.turnId,
              schema.sessionPendingToolCalls.callId,
            ],
          })
          .returning({ id: schema.sessionPendingToolCalls.id });
        if (inserted.length === 0) {
          const [pending] = await tx
            .select({
              id: schema.sessionPendingToolCalls.id,
              modelToolOutputTruncationTokens:
                schema.sessionPendingToolCalls.modelToolOutputTruncationTokens,
            })
            .from(schema.sessionPendingToolCalls)
            .where(
              and(
                eq(schema.sessionPendingToolCalls.workspaceId, input.workspaceId),
                eq(schema.sessionPendingToolCalls.sessionId, input.sessionId),
                eq(schema.sessionPendingToolCalls.turnId, input.turnId),
                eq(schema.sessionPendingToolCalls.callId, input.callId),
              ),
            )
            .for("update")
            .limit(1);
          if (!pending) {
            throw new Error(
              `Pending SDK tool call disappeared during registration: ${input.callId}`,
            );
          }
          assertPendingToolOutputPolicyMatches(
            pending.modelToolOutputTruncationTokens,
            input.modelToolOutputTruncationTokens,
            input.callId,
          );
          if (
            pending.modelToolOutputTruncationTokens === null &&
            input.modelToolOutputTruncationTokens !== undefined
          ) {
            await tx
              .update(schema.sessionPendingToolCalls)
              .set({
                modelToolOutputTruncationTokens: input.modelToolOutputTruncationTokens,
              })
              .where(eq(schema.sessionPendingToolCalls.id, pending.id));
          }
        }
        return { accepted: true, registered: inserted.length === 1 };
      }),
  );
}

/**
 * Clear one completed Toolspace receipt after its attempt-fenced output event is
 * durable. If control already replaced the attempt, its settlement transaction
 * owns the receipt and will retain an explicit outcome-unknown or the durable
 * output event instead.
 */
export async function clearPendingSessionToolspaceCall(
  db: Database,
  input: Omit<PendingSessionToolCallInput, "callType" | "callItem">,
): Promise<{ accepted: boolean; cleared: boolean }> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (tx) => {
        const fence = await lockTurnAttemptWriteFenceTx(tx as unknown as Database, {
          workspaceId: input.workspaceId,
          sessionId: input.sessionId,
          turnId: input.turnId,
          executionGeneration: input.executionGeneration,
          attemptId: input.attemptId,
        });
        if (!fence.allowed) return { accepted: false, cleared: false };
        const deleted = await tx
          .delete(schema.sessionPendingToolCalls)
          .where(
            and(
              eq(schema.sessionPendingToolCalls.workspaceId, input.workspaceId),
              eq(schema.sessionPendingToolCalls.sessionId, input.sessionId),
              eq(schema.sessionPendingToolCalls.turnId, input.turnId),
              eq(schema.sessionPendingToolCalls.attemptId, input.attemptId),
              eq(schema.sessionPendingToolCalls.callId, input.callId),
              eq(schema.sessionPendingToolCalls.callType, "toolspace_call"),
            ),
          )
          .returning({ id: schema.sessionPendingToolCalls.id });
        return { accepted: true, cleared: deleted.length === 1 };
      }),
  );
}

/** Record the raw SDK result without dropping the call receipt. */
export async function recordPendingSessionToolCallResult(
  db: Database,
  input: Omit<PendingSessionToolCallInput, "callType" | "callItem"> & {
    resultItem: Record<string, unknown>;
  },
): Promise<{ accepted: boolean; recorded: boolean }> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (tx) => {
        const fence = await lockTurnAttemptWriteFenceTx(tx, {
          workspaceId: input.workspaceId,
          sessionId: input.sessionId,
          turnId: input.turnId,
          executionGeneration: input.executionGeneration,
          attemptId: input.attemptId,
        });
        if (!fence.allowed) {
          return { accepted: false, recorded: false };
        }
        const [pending] = await tx
          .select()
          .from(schema.sessionPendingToolCalls)
          .where(
            and(
              eq(schema.sessionPendingToolCalls.workspaceId, input.workspaceId),
              eq(schema.sessionPendingToolCalls.sessionId, input.sessionId),
              eq(schema.sessionPendingToolCalls.turnId, input.turnId),
              eq(schema.sessionPendingToolCalls.callId, input.callId),
            ),
          )
          .for("update")
          .limit(1);
        if (!pending) return { accepted: true, recorded: false };
        assertPendingToolOutputPolicyMatches(
          pending.modelToolOutputTruncationTokens,
          input.modelToolOutputTruncationTokens,
          input.callId,
        );
        if (
          pending.modelToolOutputTruncationTokens === null &&
          input.modelToolOutputTruncationTokens !== undefined
        ) {
          await tx
            .update(schema.sessionPendingToolCalls)
            .set({
              modelToolOutputTruncationTokens: input.modelToolOutputTruncationTokens,
            })
            .where(eq(schema.sessionPendingToolCalls.id, pending.id));
        }
        const resultType = TOOL_RESULT_TYPE_BY_CALL_TYPE[pending.callType];
        if (
          !resultType ||
          historyItemType(input.resultItem) !== resultType ||
          historyCallId(input.resultItem) !== input.callId
        ) {
          throw new Error(`SDK tool result does not settle ${pending.callType}:${input.callId}`);
        }
        const recorded = await tx
          .update(schema.sessionPendingToolCalls)
          .set({
            resultItem: sanitizeModelPayload(input.resultItem),
            resultRecordedAt: new Date(),
          })
          .where(
            and(
              eq(schema.sessionPendingToolCalls.id, pending.id),
              sql`${schema.sessionPendingToolCalls.resultItem} is null`,
            ),
          )
          .returning({ id: schema.sessionPendingToolCalls.id });
        return {
          accepted: true,
          recorded: recorded.length === 1,
        };
      }),
  );
}

/**
 * Remove completed receipts only after the full SDK call/result batch is
 * durable. Until then every raw result remains available to an attempt-ending
 * transaction, including reverse-completing parallel calls.
 */
export async function clearDurablePendingSessionToolCalls(
  db: Database,
  input: Omit<PendingSessionToolCallInput, "callId" | "callType" | "callItem"> & {
    callIds: string[];
  },
): Promise<{ accepted: boolean; cleared: number }> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (tx) => {
        const fence = await lockTurnAttemptWriteFenceTx(tx, {
          workspaceId: input.workspaceId,
          sessionId: input.sessionId,
          turnId: input.turnId,
          executionGeneration: input.executionGeneration,
          attemptId: input.attemptId,
        });
        if (!fence.allowed) return { accepted: false, cleared: 0 };
        if (input.callIds.length === 0) return { accepted: true, cleared: 0 };
        const pending = await tx
          .select()
          .from(schema.sessionPendingToolCalls)
          .where(
            and(
              eq(schema.sessionPendingToolCalls.workspaceId, input.workspaceId),
              eq(schema.sessionPendingToolCalls.sessionId, input.sessionId),
              eq(schema.sessionPendingToolCalls.turnId, input.turnId),
              inArray(schema.sessionPendingToolCalls.callId, input.callIds),
              sql`${schema.sessionPendingToolCalls.resultItem} is not null`,
            ),
          )
          .for("update");
        if (pending.length === 0) return { accepted: true, cleared: 0 };
        const history = await tx
          .select({
            position: schema.sessionHistoryItems.position,
            item: schema.sessionHistoryItems.item,
          })
          .from(schema.sessionHistoryItems)
          .where(
            and(
              eq(schema.sessionHistoryItems.workspaceId, input.workspaceId),
              eq(schema.sessionHistoryItems.sessionId, input.sessionId),
              eq(schema.sessionHistoryItems.turnId, input.turnId),
            ),
          );
        const durableIds = pending
          .filter((call) => {
            const resultType = TOOL_RESULT_TYPE_BY_CALL_TYPE[call.callType];
            if (!resultType) return false;
            const durableCall = history.find(
              ({ item }) =>
                historyItemType(item) === call.callType && historyCallId(item) === call.callId,
            );
            return Boolean(
              durableCall &&
              history.some(
                ({ item, position }) =>
                  position > durableCall.position &&
                  historyItemType(item) === resultType &&
                  historyCallId(item) === call.callId,
              ),
            );
          })
          .map((call) => call.id);
        if (durableIds.length > 0) {
          await tx
            .delete(schema.sessionPendingToolCalls)
            .where(inArray(schema.sessionPendingToolCalls.id, durableIds));
        }
        return { accepted: true, cleared: durableIds.length };
      }),
  );
}

export async function getSessionHistoryItems(
  db: Database,
  workspaceId: string,
  sessionId: string,
): Promise<Array<{ position: number; item: Record<string, unknown> }>> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const rows = await scopedDb
      .select({
        position: schema.sessionHistoryItems.position,
        item: schema.sessionHistoryItems.item,
      })
      .from(schema.sessionHistoryItems)
      .where(
        and(
          eq(schema.sessionHistoryItems.workspaceId, workspaceId),
          eq(schema.sessionHistoryItems.sessionId, sessionId),
        ),
      )
      .orderBy(schema.sessionHistoryItems.position);
    return rows;
  });
}

/**
 * The LIVE conversation-truth read path: only active rows, position-ordered.
 * After a client-side context compaction this returns [retained user messages,
 * active summary]; with no compaction yet it equals
 * getSessionHistoryItems. The model-facing read path uses this so superseded
 * (summarized-away) prefix rows are excluded while the full transcript stays in
 * the table as an audit trail.
 */
export async function getActiveSessionHistoryItems(
  db: Database,
  workspaceId: string,
  sessionId: string,
): Promise<
  Array<{
    position: number;
    item: Record<string, unknown>;
    producerCodexCredentialId: string | null;
    providerArtifactInvalidatedAt: Date | null;
  }>
> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const rows = await scopedDb
      .select({
        position: schema.sessionHistoryItems.position,
        item: schema.sessionHistoryItems.item,
        producerCodexCredentialId: schema.sessionHistoryItems.producerCodexCredentialId,
        providerArtifactInvalidatedAt: schema.sessionHistoryItems.providerArtifactInvalidatedAt,
      })
      .from(schema.sessionHistoryItems)
      .where(
        and(
          eq(schema.sessionHistoryItems.workspaceId, workspaceId),
          eq(schema.sessionHistoryItems.sessionId, sessionId),
          eq(schema.sessionHistoryItems.active, true),
        ),
      )
      .orderBy(schema.sessionHistoryItems.position);
    return rows;
  });
}

/**
 * Count of ACTIVE (live, model-facing) history rows for a session. This is the
 * length of the history the next turn is seeded from — the dual-write slice
 * index — which after a compaction is far smaller than the total persisted-row
 * count (countSessionHistoryItems still includes the superseded prefix).
 */
export async function countActiveSessionHistoryItems(
  db: Database,
  workspaceId: string,
  sessionId: string,
): Promise<number> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const [row] = await scopedDb
      .select({
        count: sql<number>`count(*)`,
      })
      .from(schema.sessionHistoryItems)
      .where(
        and(
          eq(schema.sessionHistoryItems.workspaceId, workspaceId),
          eq(schema.sessionHistoryItems.sessionId, sessionId),
          eq(schema.sessionHistoryItems.active, true),
        ),
      );
    return Number(row?.count ?? 0);
  });
}

/**
 * Result-item types and the CALL type that settles each. Kept byte-for-byte in
 * sync with the runtime sanitizer's RESULT_TYPE_BY_CALL_TYPE and the repair
 * migration (0014). The repair, the read-path sanitizer, and this spec all share
 * one definition of a tool-call pair.
 */
const REPAIR_CALL_TYPE_BY_RESULT_TYPE: Record<string, string> = {
  function_call_result: "function_call",
  computer_call_result: "computer_call",
  shell_call_output: "shell_call",
  apply_patch_call_output: "apply_patch_call",
};

function repairCallIdOf(item: unknown): string | undefined {
  if (!item || typeof item !== "object") {
    return undefined;
  }
  const record = item as { callId?: unknown; call_id?: unknown };
  if (typeof record.callId === "string") {
    return record.callId;
  }
  if (typeof record.call_id === "string") {
    return record.call_id;
  }
  return undefined;
}

function repairItemType(item: unknown): string | undefined {
  if (!item || typeof item !== "object") {
    return undefined;
  }
  const type = (item as { type?: unknown }).type;
  return typeof type === "string" ? type : undefined;
}

/**
 * Pure TypeScript SPEC for the one-time orphan repair (migration 0014),
 * mirroring its SQL WHERE clause so the deletion rule is unit-testable without a
 * database. Given the ACTIVE history rows of a single session in position order,
 * returns the indices of the orphaned tool-call RESULT rows the repair deletes.
 *
 * An orphan is a result-type row (function_call_result / computer_call_result /
 * shell_call_output / apply_patch_call_output) with no matching CALL of the
 * paired type, same correlation id (camelCase `callId` OR snake_case `call_id`),
 * at a STRICTLY EARLIER position in the same session. This is exactly the
 * session-bricking row the Responses API 400s on ("No tool call found for
 * function call output").
 *
 * DANGLING CALLS (a call with no result yet) are intentionally NOT returned: a
 * call awaiting a not-yet-settled result is valid, not corruption. Only unpaired
 * results are removed.
 *
 * EXISTENCE, not consumption: like the migration's `NOT EXISTS (... earlier
 * call ...)`, a result is kept whenever ANY earlier matching call exists. A
 * second result that re-uses a call_id already settled earlier is therefore NOT
 * flagged here (a matching call still exists before it) — this conservative
 * choice matches the SQL exactly and never deletes a row whose call is present;
 * the read-path sanitizer (which consumes calls one-for-one) still drops such a
 * rare duplicate in-memory, so the model request stays valid regardless.
 *
 * Callers pass rows already ordered by position. The earlier-position test is
 * by array order (the SQL orders by the numeric position column, which the read
 * path also orders by), so identical inputs yield identical decisions.
 */
export function orphanedResultRowIndicesForRepair(
  activeRowsInPositionOrder: ReadonlyArray<{ item: Record<string, unknown> }>,
): number[] {
  // call_ids of CALLs seen so far, per matching result type. A result is an
  // orphan unless a call of its paired type with the same id appeared earlier.
  const seenCallIdsByResultType = new Map<string, Set<string>>();
  // Pre-index every call type to the result type(s) it can settle.
  const resultTypeByCallType: Record<string, string> = {};
  for (const [resultType, callType] of Object.entries(REPAIR_CALL_TYPE_BY_RESULT_TYPE)) {
    resultTypeByCallType[callType] = resultType;
  }
  const orphanIndices: number[] = [];
  activeRowsInPositionOrder.forEach((row, index) => {
    const type = repairItemType(row.item);
    const callId = repairCallIdOf(row.item);
    if (!type || !callId) {
      return;
    }
    const settlesResultType = resultTypeByCallType[type];
    if (settlesResultType) {
      // This row is a CALL: record its id so a later matching result is paired.
      const seen = seenCallIdsByResultType.get(settlesResultType) ?? new Set<string>();
      seen.add(callId);
      seenCallIdsByResultType.set(settlesResultType, seen);
      return;
    }
    if (REPAIR_CALL_TYPE_BY_RESULT_TYPE[type]) {
      // This row is a RESULT: orphan unless an earlier matching call was seen.
      const seen = seenCallIdsByResultType.get(type);
      if (!seen || !seen.has(callId)) {
        orphanIndices.push(index);
      }
    }
  });
  return orphanIndices;
}

export type ApplyContextCompactionResult =
  | {
      applied: true;
      supersededFrom: number;
      summaryPosition: number;
      events: SessionEvent[];
    }
  | { applied: false; reason: TurnAttemptFenceRejectReason };

/**
 * Atomically install the Codex-style replacement history for one exact turn
 * attempt. The old active rows remain as inactive audit evidence; the retained
 * user messages and summary receive fresh whole-number positions after every
 * existing row. A paused, replaced, recovered, or terminal attempt cannot
 * mutate conversation truth.
 */
export async function applyContextCompaction(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sessionId: string;
    turnId: string;
    expectedExecutionGeneration: number;
    expectedAttemptId: string;
    replacementItems: Array<Record<string, unknown>>;
    summaryItem: Record<string, unknown>;
    replacementInputTokens: number;
    clearRequestedCompaction?: boolean;
    eventPayload?: Record<string, unknown>;
    /** Tag inserted history rows with the Codex credential that produced them. */
    producerCodexCredentialId?: string | null;
  },
): Promise<ApplyContextCompactionResult> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      return await scopedDb.transaction(async (tx) => {
        const fence = await lockTurnAttemptWriteFenceTx(tx, {
          workspaceId: input.workspaceId,
          sessionId: input.sessionId,
          turnId: input.turnId,
          executionGeneration: input.expectedExecutionGeneration,
          attemptId: input.expectedAttemptId,
        });
        if (!fence.allowed) {
          return { applied: false as const, reason: fence.reason };
        }
        const [{ maxPosition } = { maxPosition: -1 }] = await tx
          .select({
            maxPosition: sql<number>`coalesce(max(${schema.sessionHistoryItems.position}), -1)`,
          })
          .from(schema.sessionHistoryItems)
          .where(
            and(
              eq(schema.sessionHistoryItems.workspaceId, input.workspaceId),
              eq(schema.sessionHistoryItems.sessionId, input.sessionId),
            ),
          );
        const supersededFrom = Math.floor(Number(maxPosition)) + 1;
        await tx
          .update(schema.sessionHistoryItems)
          .set({ active: false })
          .where(
            and(
              eq(schema.sessionHistoryItems.workspaceId, input.workspaceId),
              eq(schema.sessionHistoryItems.sessionId, input.sessionId),
              eq(schema.sessionHistoryItems.active, true),
            ),
          );
        if (input.replacementItems.length > 0) {
          await tx.insert(schema.sessionHistoryItems).values(
            input.replacementItems.map((item, index) => ({
              accountId: input.accountId,
              workspaceId: input.workspaceId,
              sessionId: input.sessionId,
              turnId: null,
              position: supersededFrom + index,
              item: sanitizeModelPayload(item),
              active: true,
              ...(input.producerCodexCredentialId
                ? { producerCodexCredentialId: input.producerCodexCredentialId }
                : {}),
            })),
          );
        }
        const summaryPosition = supersededFrom + input.replacementItems.length;
        await tx.insert(schema.sessionHistoryItems).values({
          accountId: input.accountId,
          workspaceId: input.workspaceId,
          sessionId: input.sessionId,
          turnId: input.turnId,
          position: summaryPosition,
          item: sanitizeModelPayload(input.summaryItem),
          active: true,
          ...(input.producerCodexCredentialId
            ? { producerCodexCredentialId: input.producerCodexCredentialId }
            : {}),
        });
        const insertedEvents = input.eventPayload
          ? await tx
              .insert(schema.sessionEvents)
              .values({
                accountId: input.accountId,
                workspaceId: input.workspaceId,
                sessionId: input.sessionId,
                turnId: input.turnId,
                turnGeneration: input.expectedExecutionGeneration,
                turnAttemptId: input.expectedAttemptId,
                turnAssociation: "current",
                sequence: fence.session.lastSequence + 1,
                type: "session.context.compacted",
                payload: sanitizeEventPayload({
                  ...input.eventPayload,
                  summaryPosition,
                }),
                occurredAt: new Date(),
              })
              .returning()
          : [];
        await tx
          .update(schema.sessions)
          .set({
            lastInputTokens: Math.max(0, Math.floor(input.replacementInputTokens)),
            ...(input.clearRequestedCompaction ? { compactRequested: false } : {}),
            ...(insertedEvents.length > 0
              ? {
                  lastSequence: fence.session.lastSequence + insertedEvents.length,
                }
              : {}),
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(schema.sessions.workspaceId, input.workspaceId),
              eq(schema.sessions.id, input.sessionId),
            ),
          );
        return {
          applied: true as const,
          supersededFrom,
          summaryPosition,
          events: insertedEvents.map(mapEvent),
        };
      });
    },
  );
}

/**
 * Attempt-fenced visible start of a compaction provider call. Emitted before
 * the summarizer / remote-v2 request so the timeline can show progress while
 * the opaque checkpoint is being built. A fenced attempt writes nothing.
 */
export async function recordStartedContextCompaction(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sessionId: string;
    turnId: string;
    expectedExecutionGeneration: number;
    expectedAttemptId: string;
    trigger: "auto" | "operator" | "proactive" | "overflow";
    implementation?: string;
    estimatedTokensBefore?: number;
  },
): Promise<
  | { recorded: true; events: SessionEvent[] }
  | { recorded: false; reason: TurnAttemptFenceRejectReason }
> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (tx) => {
        const fence = await lockTurnAttemptWriteFenceTx(tx, {
          workspaceId: input.workspaceId,
          sessionId: input.sessionId,
          turnId: input.turnId,
          executionGeneration: input.expectedExecutionGeneration,
          attemptId: input.expectedAttemptId,
        });
        if (!fence.allowed) return { recorded: false as const, reason: fence.reason };
        const inserted = await tx
          .insert(schema.sessionEvents)
          .values({
            accountId: input.accountId,
            workspaceId: input.workspaceId,
            sessionId: input.sessionId,
            turnId: input.turnId,
            turnGeneration: input.expectedExecutionGeneration,
            turnAttemptId: input.expectedAttemptId,
            turnAssociation: "current",
            sequence: fence.session.lastSequence + 1,
            type: "session.context.compaction.started",
            payload: sanitizeEventPayload({
              trigger: input.trigger,
              ...(input.implementation ? { implementation: input.implementation } : {}),
              ...(typeof input.estimatedTokensBefore === "number"
                ? { estimatedTokensBefore: input.estimatedTokensBefore }
                : {}),
            }),
            occurredAt: new Date(),
          })
          .returning();
        await tx
          .update(schema.sessions)
          .set({
            lastSequence: fence.session.lastSequence + 1,
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(schema.sessions.workspaceId, input.workspaceId),
              eq(schema.sessions.id, input.sessionId),
            ),
          );
        return { recorded: true as const, events: inserted.map(mapEvent) };
      }),
  );
}

/**
 * Atomically record that an operator compaction request needed no replacement
 * and consume it. The exact running attempt owns both the visible event and
 * the clear, just like a successful replacement; a paused, recovered, or
 * superseded attempt can do neither and leaves the request pending.
 */
export async function recordSkippedContextCompaction(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sessionId: string;
    turnId: string;
    expectedExecutionGeneration: number;
    expectedAttemptId: string;
    reason:
      | "no_history"
      | "replacement_not_smaller"
      | "replacement_unchanged"
      | "summarization_failed";
    /**
     * When false, record the visible skip even if no operator `/compact` is
     * pending (auto/overflow paths that already emitted `compaction.started`).
     * Defaults to true so idle-operator consumption stays request-gated.
     */
    requirePendingRequest?: boolean;
    /** When false, leave `compactRequested` untouched. Defaults to true. */
    clearRequestedCompaction?: boolean;
  },
): Promise<
  | { recorded: true; events: SessionEvent[] }
  | {
      recorded: false;
      reason: TurnAttemptFenceRejectReason | "request_not_pending";
    }
> {
  const requirePendingRequest = input.requirePendingRequest !== false;
  const clearRequestedCompaction = input.clearRequestedCompaction !== false;
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (tx) => {
        const fence = await lockTurnAttemptWriteFenceTx(tx, {
          workspaceId: input.workspaceId,
          sessionId: input.sessionId,
          turnId: input.turnId,
          executionGeneration: input.expectedExecutionGeneration,
          attemptId: input.expectedAttemptId,
        });
        if (!fence.allowed) return { recorded: false as const, reason: fence.reason };
        if (requirePendingRequest && !fence.session.compactRequested) {
          return {
            recorded: false as const,
            reason: "request_not_pending" as const,
          };
        }
        const inserted = await tx
          .insert(schema.sessionEvents)
          .values({
            accountId: input.accountId,
            workspaceId: input.workspaceId,
            sessionId: input.sessionId,
            turnId: input.turnId,
            turnGeneration: input.expectedExecutionGeneration,
            turnAttemptId: input.expectedAttemptId,
            turnAssociation: "current",
            sequence: fence.session.lastSequence + 1,
            type: "session.context.compaction.skipped",
            payload: sanitizeEventPayload({ reason: input.reason }),
            occurredAt: new Date(),
          })
          .returning();
        await tx
          .update(schema.sessions)
          .set({
            ...(clearRequestedCompaction ? { compactRequested: false } : {}),
            lastSequence: fence.session.lastSequence + 1,
            updatedAt: new Date(),
          })
          .where(
            and(
              eq(schema.sessions.workspaceId, input.workspaceId),
              eq(schema.sessions.id, input.sessionId),
              ...(clearRequestedCompaction ? [eq(schema.sessions.compactRequested, true)] : []),
            ),
          );
        return { recorded: true as const, events: inserted.map(mapEvent) };
      }),
  );
}

/**
 * The next free WHOLE-NUMBER history position for a session: one past the
 * largest existing position (active or superseded), floored so the synthetic
 * summary's fractional half-step never shifts the count. The dual-write
 * watermark uses this to append new rows at fresh absolute positions, decoupled
 * from the in-memory history length (which, after a compaction, is far shorter
 * than the total persisted-row count and so cannot serve as the next position).
 */
export async function nextSessionHistoryPosition(
  db: Database,
  workspaceId: string,
  sessionId: string,
): Promise<number> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const [row] = await scopedDb
      .select({
        maxPosition: sql<number | null>`max(${schema.sessionHistoryItems.position})`,
      })
      .from(schema.sessionHistoryItems)
      .where(
        and(
          eq(schema.sessionHistoryItems.workspaceId, workspaceId),
          eq(schema.sessionHistoryItems.sessionId, sessionId),
        ),
      );
    const max = row?.maxPosition;
    return max === null || max === undefined ? 0 : Math.floor(Number(max)) + 1;
  });
}

/**
 * Record the actual input-token count of the most recent turn's final model
 * call, for the next turn's pre-read compaction trigger.
 */
export async function setSessionLastInputTokensForTurnAttempt(
  db: Database,
  input: {
    workspaceId: string;
    sessionId: string;
    turnId: string;
    expectedExecutionGeneration: number;
    expectedAttemptId: string;
    lastInputTokens: number;
  },
): Promise<boolean> {
  return await withWorkspaceRls(db, input.workspaceId, async (scopedDb) => {
    return await scopedDb.transaction(async (tx) => {
      const fence = await lockTurnAttemptWriteFenceTx(tx, {
        workspaceId: input.workspaceId,
        sessionId: input.sessionId,
        turnId: input.turnId,
        executionGeneration: input.expectedExecutionGeneration,
        attemptId: input.expectedAttemptId,
      });
      if (!fence.allowed) return false;
      await tx
        .update(schema.sessions)
        .set({ lastInputTokens: input.lastInputTokens, updatedAt: new Date() })
        .where(
          and(
            eq(schema.sessions.workspaceId, input.workspaceId),
            eq(schema.sessions.id, input.sessionId),
          ),
        );
      return true;
    });
  });
}

/** The neutral boundary left as the sole active history row after a clear. */
export function clearedContextMarkerItem(): Record<string, unknown> {
  return { type: "message", role: "user", content: "[context cleared]" };
}

export type ClearSessionContextResult = {
  /** Active history rows superseded (active=true -> false). */
  supersededItems: number;
  /** Position of the inserted neutral boundary marker. */
  markerPosition: number;
};

export class SessionContextBusyError extends Error {
  constructor(public readonly status: string) {
    super(`session is ${status}; Pause must settle before context can be cleared`);
    this.name = "SessionContextBusyError";
  }
}

/**
 * Clear a session's conversation context in ONE transaction, audit-preserving
 * and idempotent:
 *
 *  (a) supersede every active session_history_items row (active=true -> false).
 *      Nothing is deleted — the full transcript stays as an audit trail, same
 *      pattern as applyContextCompaction.
 *  (b) insert ONE active neutral boundary marker at max(position)+1. Ordinary
 *      inference reads only this canonical history store; SDK RunState remains
 *      reserved for an approval that paused mid-turn, and the API forbids a
 *      clear while such an approval or active turn exists.
 *
 * Also resets last_input_tokens to 0 so the next turn's compaction trigger
 * starts fresh against the now-short context.
 *
 * Idempotent: a re-run supersedes the (now sole, already-marker) active row,
 * inserts another marker at the next position. The post-condition (one active
 * marker row) holds.
 */
export async function clearSessionContext(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sessionId: string;
  },
): Promise<ClearSessionContextResult> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      return await scopedDb.transaction(async (tx) => {
        const [workspace] = await tx
          .select({ id: schema.workspaces.id })
          .from(schema.workspaces)
          .where(eq(schema.workspaces.id, input.workspaceId))
          .for("update")
          .limit(1);
        if (!workspace) throw new Error(`Workspace not found: ${input.workspaceId}`);
        const [session] = await tx
          .select({
            status: schema.sessions.status,
            activeTurnId: schema.sessions.activeTurnId,
          })
          .from(schema.sessions)
          .where(
            and(
              eq(schema.sessions.workspaceId, input.workspaceId),
              eq(schema.sessions.id, input.sessionId),
            ),
          )
          .for("update")
          .limit(1);
        if (!session) throw new Error(`Session not found: ${input.sessionId}`);
        if (
          session.activeTurnId !== null ||
          !["idle", "failed", "cancelled"].includes(session.status)
        ) {
          throw new SessionContextBusyError(session.status);
        }
        const supersededRows = await tx
          .update(schema.sessionHistoryItems)
          .set({ active: false })
          .where(
            and(
              eq(schema.sessionHistoryItems.workspaceId, input.workspaceId),
              eq(schema.sessionHistoryItems.sessionId, input.sessionId),
              eq(schema.sessionHistoryItems.active, true),
            ),
          )
          .returning({ id: schema.sessionHistoryItems.id });

        const [{ maxPosition } = { maxPosition: -1 }] = await tx
          .select({
            maxPosition: sql<number>`coalesce(max(${schema.sessionHistoryItems.position}), -1)`,
          })
          .from(schema.sessionHistoryItems)
          .where(
            and(
              eq(schema.sessionHistoryItems.workspaceId, input.workspaceId),
              eq(schema.sessionHistoryItems.sessionId, input.sessionId),
            ),
          );
        const markerPosition = Number(maxPosition) + 1;
        await tx
          .insert(schema.sessionHistoryItems)
          .values({
            accountId: input.accountId,
            workspaceId: input.workspaceId,
            sessionId: input.sessionId,
            turnId: null,
            position: markerPosition,
            item: sanitizeModelPayload(clearedContextMarkerItem()),
            active: true,
          })
          .onConflictDoNothing({
            target: [
              schema.sessionHistoryItems.workspaceId,
              schema.sessionHistoryItems.sessionId,
              schema.sessionHistoryItems.position,
            ],
          });

        await tx
          .update(schema.sessions)
          .set({ lastInputTokens: 0, updatedAt: new Date() })
          .where(
            and(
              eq(schema.sessions.workspaceId, input.workspaceId),
              eq(schema.sessions.id, input.sessionId),
            ),
          );

        return { supersededItems: supersededRows.length, markerPosition };
      });
    },
  );
}

export async function countSessionHistoryItems(
  db: Database,
  workspaceId: string,
  sessionId: string,
): Promise<number> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const [row] = await scopedDb
      .select({
        count: sql<number>`count(*)`,
      })
      .from(schema.sessionHistoryItems)
      .where(
        and(
          eq(schema.sessionHistoryItems.workspaceId, workspaceId),
          eq(schema.sessionHistoryItems.sessionId, sessionId),
        ),
      );
    return Number(row?.count ?? 0);
  });
}

/**
 * Set the operator /compact request flag. The worker honors it before the next
 * turn (forced portable compaction) and clears it. Idempotent: repeated
 * requests collapse to one pending compaction.
 */
export async function requestSessionCompaction(
  db: Database,
  workspaceId: string,
  sessionId: string,
): Promise<{ wakeRevision: number; temporalWorkflowId: string }> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const [session] = await scopedDb
      .select({
        accountId: schema.sessions.accountId,
        temporalWorkflowId: schema.sessions.temporalWorkflowId,
      })
      .from(schema.sessions)
      .where(and(eq(schema.sessions.workspaceId, workspaceId), eq(schema.sessions.id, sessionId)))
      .for("update")
      .limit(1);
    if (!session) throw new Error(`Session not found: ${sessionId}`);
    await scopedDb
      .update(schema.sessions)
      .set({ compactRequested: true, updatedAt: new Date() })
      .where(and(eq(schema.sessions.workspaceId, workspaceId), eq(schema.sessions.id, sessionId)));
    const temporalWorkflowId = session.temporalWorkflowId ?? `session-${sessionId}`;
    const wakeRevision = await enqueueSessionWorkflowWakeInTransaction(scopedDb, {
      accountId: session.accountId,
      workspaceId,
      sessionId,
      temporalWorkflowId,
      reason: "compaction_requested",
    });
    return { wakeRevision, temporalWorkflowId };
  });
}

/** Read the durable /compact request without consuming it. The exact current
 * turn attempt clears the flag in the same transaction that installs the new
 * active history, so a failed or superseded summarizer cannot lose the request.
 */
export async function isSessionCompactionRequested(
  db: Database,
  workspaceId: string,
  sessionId: string,
): Promise<boolean> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const [session] = await scopedDb
      .select({ compactRequested: schema.sessions.compactRequested })
      .from(schema.sessions)
      .where(and(eq(schema.sessions.workspaceId, workspaceId), eq(schema.sessions.id, sessionId)))
      .limit(1);
    return session?.compactRequested === true;
  });
}

/**
 * Persist the session's sandbox recovery descriptor (the small versioned
 * envelope used to reattach / snapshot-restore / rebuild the sandbox),
 * decoupled from the RunState blob.
 */
export async function upsertSandboxSessionEnvelope(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sessionId: string;
    envelope: Record<string, unknown>;
  },
): Promise<void> {
  await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      await scopedDb
        .insert(schema.sandboxSessionEnvelopes)
        .values({
          accountId: input.accountId,
          workspaceId: input.workspaceId,
          sessionId: input.sessionId,
          envelope: input.envelope,
        })
        .onConflictDoUpdate({
          target: [
            schema.sandboxSessionEnvelopes.workspaceId,
            schema.sandboxSessionEnvelopes.sessionId,
          ],
          set: { envelope: input.envelope, updatedAt: new Date() },
        });
    },
  );
}

export async function getSandboxSessionEnvelope(
  db: Database,
  workspaceId: string,
  sessionId: string,
): Promise<Record<string, unknown> | null> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const [row] = await scopedDb
      .select({ envelope: schema.sandboxSessionEnvelopes.envelope })
      .from(schema.sandboxSessionEnvelopes)
      .where(
        and(
          eq(schema.sandboxSessionEnvelopes.workspaceId, workspaceId),
          eq(schema.sandboxSessionEnvelopes.sessionId, sessionId),
        ),
      )
      .limit(1);
    return row?.envelope ?? null;
  });
}

// ============================================================================
// Session recordings — the durable index for the "agent films itself proving
// the fix" loop. One row per recording; insert at start, update at
// finalize (available with the storage_key) or failure. Read-side feeds the
// list route + the signed-URL replay route (storage_key is the source of truth).
// ============================================================================

export type SessionRecordingState = (typeof schema.sessionRecordingStateValues)[number];
export type SessionRecordingMode = (typeof schema.sessionRecordingModeValues)[number];
export type SessionRecordingCodec = (typeof schema.sessionRecordingCodecValues)[number];

export type SessionRecordingRow = {
  id: string;
  workspaceId: string;
  sessionId: string;
  turnId: string | null;
  state: SessionRecordingState;
  mode: SessionRecordingMode;
  codec: SessionRecordingCodec;
  storageKey: string | null;
  sizeBytes: number | null;
  durationSeconds: number | null;
  width: number;
  height: number;
  reason: string | null;
  createdAt: Date;
  finalizedAt: Date | null;
};

function mapRecording(row: typeof schema.sessionRecordings.$inferSelect): SessionRecordingRow {
  return {
    id: row.id,
    workspaceId: row.workspaceId,
    sessionId: row.sessionId,
    turnId: row.turnId,
    state: row.state,
    mode: row.mode,
    codec: row.codec,
    storageKey: row.storageKey,
    sizeBytes: row.sizeBytes === null || row.sizeBytes === undefined ? null : Number(row.sizeBytes),
    durationSeconds:
      row.durationSeconds === null || row.durationSeconds === undefined
        ? null
        : Number(row.durationSeconds),
    width: row.width,
    height: row.height,
    reason: row.reason,
    createdAt: row.createdAt,
    finalizedAt: row.finalizedAt,
  };
}

export async function insertRecording(
  db: Database,
  input: {
    id: string;
    accountId: string;
    workspaceId: string;
    sessionId: string;
    turnId?: string | null;
    mode: SessionRecordingMode;
    codec: SessionRecordingCodec;
    width: number;
    height: number;
    reason?: string | null;
  },
): Promise<SessionRecordingRow> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      const [row] = await scopedDb
        .insert(schema.sessionRecordings)
        .values({
          id: input.id,
          accountId: input.accountId,
          workspaceId: input.workspaceId,
          sessionId: input.sessionId,
          turnId: input.turnId ?? null,
          state: "recording",
          mode: input.mode,
          codec: input.codec,
          width: input.width,
          height: input.height,
          reason: input.reason ?? null,
        })
        .returning();
      return mapRecording(row!);
    },
  );
}

export async function updateRecording(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    recordingId: string;
    state: SessionRecordingState;
    storageKey?: string | null;
    sizeBytes?: number | null;
    durationSeconds?: number | null;
    reason?: string | null;
    finalized?: boolean;
  },
): Promise<SessionRecordingRow | null> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      const set: Partial<typeof schema.sessionRecordings.$inferInsert> = {
        state: input.state,
      };
      if (input.storageKey !== undefined) set.storageKey = input.storageKey;
      if (input.sizeBytes !== undefined) set.sizeBytes = input.sizeBytes;
      if (input.durationSeconds !== undefined) set.durationSeconds = input.durationSeconds;
      if (input.reason !== undefined) set.reason = input.reason;
      if (input.finalized || input.state === "available" || input.state === "failed") {
        set.finalizedAt = new Date();
      }
      const [row] = await scopedDb
        .update(schema.sessionRecordings)
        .set(set)
        .where(
          and(
            eq(schema.sessionRecordings.workspaceId, input.workspaceId),
            eq(schema.sessionRecordings.id, input.recordingId),
          ),
        )
        .returning();
      return row ? mapRecording(row) : null;
    },
  );
}

/**
 * Hard-delete a recording row. Used to DISCARD an on-turn recording that captured
 * NO computer-use activity (a plain text turn): the row was inserted at
 * `beginRecording` (state "recording") but the turn never drove the desktop, so it
 * is removed entirely rather than surfaced as a phantom recording or a failure. No
 * other table FK-references session_recordings, so the delete is self-contained.
 */
export async function deleteRecording(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    recordingId: string;
  },
): Promise<void> {
  await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      await scopedDb
        .delete(schema.sessionRecordings)
        .where(
          and(
            eq(schema.sessionRecordings.workspaceId, input.workspaceId),
            eq(schema.sessionRecordings.id, input.recordingId),
          ),
        );
    },
  );
}

/**
 * Close an attempt-owned recording that could not reach the atomic turn
 * settlement. The accepted recording.started event is the durable ownership
 * receipt: cleanup is allowed only for the exact turn generation and attempt
 * that created this recording id. No timeline event is emitted from this
 * hygiene path.
 */
export async function abandonRecordingForTurnAttempt(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sessionId: string;
    turnId: string;
    executionGeneration: number;
    attemptId: string;
    recordingId: string;
    disposition: "failed" | "discard";
    reason: string;
  },
): Promise<boolean> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (tx) => {
        const [recording] = await tx
          .select({ id: schema.sessionRecordings.id })
          .from(schema.sessionRecordings)
          .where(
            and(
              eq(schema.sessionRecordings.accountId, input.accountId),
              eq(schema.sessionRecordings.workspaceId, input.workspaceId),
              eq(schema.sessionRecordings.sessionId, input.sessionId),
              eq(schema.sessionRecordings.turnId, input.turnId),
              eq(schema.sessionRecordings.id, input.recordingId),
              eq(schema.sessionRecordings.mode, "on-turn"),
              inArray(schema.sessionRecordings.state, ["recording", "finalizing"]),
            ),
          )
          .for("update")
          .limit(1);
        if (!recording) return false;
        const [started] = await tx
          .select({ id: schema.sessionEvents.id })
          .from(schema.sessionEvents)
          .where(
            and(
              eq(schema.sessionEvents.workspaceId, input.workspaceId),
              eq(schema.sessionEvents.sessionId, input.sessionId),
              eq(schema.sessionEvents.turnId, input.turnId),
              eq(schema.sessionEvents.turnGeneration, input.executionGeneration),
              eq(schema.sessionEvents.turnAttemptId, input.attemptId),
              eq(schema.sessionEvents.turnAssociation, "current"),
              eq(schema.sessionEvents.type, "recording.started"),
              eq(sql<string>`${schema.sessionEvents.payload} ->> 'recordingId'`, input.recordingId),
            ),
          )
          .limit(1);
        if (!started) return false;
        if (input.disposition === "discard") {
          await tx
            .delete(schema.sessionRecordings)
            .where(eq(schema.sessionRecordings.id, recording.id));
        } else {
          await tx
            .update(schema.sessionRecordings)
            .set({
              state: "failed",
              reason: input.reason.slice(0, 2_000),
              finalizedAt: new Date(),
            })
            .where(eq(schema.sessionRecordings.id, recording.id));
        }
        return true;
      }),
  );
}

export async function getRecording(
  db: Database,
  workspaceId: string,
  recordingId: string,
): Promise<SessionRecordingRow | null> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const [row] = await scopedDb
      .select()
      .from(schema.sessionRecordings)
      .where(
        and(
          eq(schema.sessionRecordings.workspaceId, workspaceId),
          eq(schema.sessionRecordings.id, recordingId),
        ),
      )
      .limit(1);
    return row ? mapRecording(row) : null;
  });
}

export async function listRecordings(
  db: Database,
  workspaceId: string,
  sessionId: string,
): Promise<SessionRecordingRow[]> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const rows = await scopedDb
      .select()
      .from(schema.sessionRecordings)
      .where(
        and(
          eq(schema.sessionRecordings.workspaceId, workspaceId),
          eq(schema.sessionRecordings.sessionId, sessionId),
        ),
      )
      .orderBy(desc(schema.sessionRecordings.createdAt));
    return rows.map(mapRecording);
  });
}

// ============================================================================
// Channel-A interactive PTY sessions (P4.4) — the ptyId <-> exec-session-id map.
// The ONLY new persistent state Channel A needs; FS/Git reads persist nothing.
// ============================================================================

export type SandboxPtySessionRow = {
  id: string;
  accountId: string;
  workspaceId: string;
  sessionId: string;
  leaseId: string | null;
  sandboxGroupId: string | null;
  retainedProcessId: string | null;
  openAdmissionId: string | null;
  execSessionId: number | null;
  leaseEpoch: number;
  providerBackend: string | null;
  providerInstanceId: string | null;
  routeKind: "home" | "active" | null;
  routeTargetId: string | null;
  routeEpoch: number | null;
  cols: number;
  rows: number;
  shell: string;
  cwd: string;
  status: "open" | "closed";
  openedBy: string;
  lastInputAt: string;
  createdAt: string;
  closedAt: string | null;
};

export type SandboxPtyProcessIdentity = {
  leaseId: string;
  sandboxGroupId: string;
  retainedProcessId: string;
  openAdmissionId: string;
  execSessionId: number;
  leaseEpoch: number;
  providerBackend: string;
  providerInstanceId: string;
  routeKind: "home" | "active";
  routeTargetId: string | null;
  routeEpoch: number;
};

export type SandboxOpenPtySessionRow = Omit<
  SandboxPtySessionRow,
  keyof SandboxPtyProcessIdentity | "status"
> &
  SandboxPtyProcessIdentity & { status: "open" };

function mapPtySession(row: typeof schema.sandboxPtySessions.$inferSelect): SandboxPtySessionRow {
  return {
    id: row.id,
    accountId: row.accountId,
    workspaceId: row.workspaceId,
    sessionId: row.sessionId,
    leaseId: row.leaseId ?? null,
    sandboxGroupId: row.sandboxGroupId ?? null,
    retainedProcessId: row.retainedProcessId ?? null,
    openAdmissionId: row.openAdmissionId ?? null,
    execSessionId: row.execSessionId ?? null,
    leaseEpoch: row.leaseEpoch,
    providerBackend: row.providerBackend ?? null,
    providerInstanceId: row.providerInstanceId ?? null,
    routeKind: (row.routeKind as "home" | "active" | null) ?? null,
    routeTargetId: row.routeTargetId ?? null,
    routeEpoch: row.routeEpoch ?? null,
    cols: row.cols,
    rows: row.rows,
    shell: row.shell,
    cwd: row.cwd,
    status: row.status as "open" | "closed",
    openedBy: row.openedBy,
    lastInputAt: row.lastInputAt.toISOString(),
    createdAt: row.createdAt.toISOString(),
    closedAt: row.closedAt ? row.closedAt.toISOString() : null,
  };
}

function mapOpenPtySession(
  row: typeof schema.sandboxPtySessions.$inferSelect,
): SandboxOpenPtySessionRow {
  const mapped = mapPtySession(row);
  if (
    mapped.status !== "open" ||
    mapped.leaseId === null ||
    mapped.sandboxGroupId === null ||
    mapped.retainedProcessId === null ||
    mapped.openAdmissionId === null ||
    mapped.execSessionId === null ||
    mapped.execSessionId <= 0 ||
    mapped.providerBackend === null ||
    mapped.providerInstanceId === null ||
    mapped.routeKind === null ||
    mapped.routeEpoch === null
  ) {
    throw new Error("Open PTY row lacks exact retained-process identity");
  }
  return mapped as SandboxOpenPtySessionRow;
}

function exactPtyIdentityPredicates(identity: SandboxPtyProcessIdentity): SQL[] {
  return [
    eq(schema.sandboxPtySessions.leaseId, identity.leaseId),
    eq(schema.sandboxPtySessions.sandboxGroupId, identity.sandboxGroupId),
    eq(schema.sandboxPtySessions.retainedProcessId, identity.retainedProcessId),
    eq(schema.sandboxPtySessions.openAdmissionId, identity.openAdmissionId),
    eq(schema.sandboxPtySessions.execSessionId, identity.execSessionId),
    eq(schema.sandboxPtySessions.leaseEpoch, identity.leaseEpoch),
    eq(schema.sandboxPtySessions.providerBackend, identity.providerBackend),
    eq(schema.sandboxPtySessions.providerInstanceId, identity.providerInstanceId),
    eq(schema.sandboxPtySessions.routeKind, identity.routeKind),
    identity.routeTargetId === null
      ? isNull(schema.sandboxPtySessions.routeTargetId)
      : eq(schema.sandboxPtySessions.routeTargetId, identity.routeTargetId),
    eq(schema.sandboxPtySessions.routeEpoch, identity.routeEpoch),
  ];
}

export async function insertPtySession(
  db: Database,
  input: {
    id: string;
    accountId: string;
    workspaceId: string;
    sessionId: string;
    identity: SandboxPtyProcessIdentity;
    cols: number;
    rows: number;
    shell: string;
    cwd: string;
    openedBy: string;
  },
): Promise<SandboxOpenPtySessionRow> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      const [row] = await scopedDb
        .insert(schema.sandboxPtySessions)
        .values({
          id: input.id,
          accountId: input.accountId,
          workspaceId: input.workspaceId,
          sessionId: input.sessionId,
          leaseId: input.identity.leaseId,
          sandboxGroupId: input.identity.sandboxGroupId,
          retainedProcessId: input.identity.retainedProcessId,
          openAdmissionId: input.identity.openAdmissionId,
          execSessionId: input.identity.execSessionId,
          leaseEpoch: input.identity.leaseEpoch,
          providerBackend: input.identity.providerBackend,
          providerInstanceId: input.identity.providerInstanceId,
          routeKind: input.identity.routeKind,
          routeTargetId: input.identity.routeTargetId,
          routeEpoch: input.identity.routeEpoch,
          cols: input.cols,
          rows: input.rows,
          shell: input.shell,
          cwd: input.cwd,
          status: "open",
          openedBy: input.openedBy,
        })
        .returning();
      return mapOpenPtySession(row!);
    },
  );
}

/** Read an OPEN PTY row by ptyId. Returns null when absent or already closed. */
export async function getOpenPtySession(
  db: Database,
  input: { workspaceId: string; sessionId: string; ptyId: string },
): Promise<SandboxOpenPtySessionRow | null> {
  return await withWorkspaceRls(db, input.workspaceId, async (scopedDb) => {
    const [row] = await scopedDb
      .select()
      .from(schema.sandboxPtySessions)
      .where(
        and(
          eq(schema.sandboxPtySessions.workspaceId, input.workspaceId),
          eq(schema.sandboxPtySessions.sessionId, input.sessionId),
          eq(schema.sandboxPtySessions.id, input.ptyId),
          eq(schema.sandboxPtySessions.status, "open"),
        ),
      )
      .limit(1);
    return row ? mapOpenPtySession(row) : null;
  });
}

/** Refresh activity/geometry only when the full retained-process identity still
 * matches. A numeric provider locator or PTY UUID alone is never authority. */
export async function updatePtySessionActivity(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sessionId: string;
    ptyId: string;
    identity: SandboxPtyProcessIdentity;
    cols?: number;
    rows?: number;
  },
): Promise<SandboxOpenPtySessionRow | null> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      const set: Partial<typeof schema.sandboxPtySessions.$inferInsert> = {
        lastInputAt: new Date(),
      };
      if (input.cols !== undefined) set.cols = input.cols;
      if (input.rows !== undefined) set.rows = input.rows;
      const [row] = await scopedDb
        .update(schema.sandboxPtySessions)
        .set(set)
        .where(
          and(
            eq(schema.sandboxPtySessions.workspaceId, input.workspaceId),
            eq(schema.sandboxPtySessions.sessionId, input.sessionId),
            eq(schema.sandboxPtySessions.id, input.ptyId),
            eq(schema.sandboxPtySessions.status, "open"),
            ...exactPtyIdentityPredicates(input.identity),
          ),
        )
        .returning();
      return row ? mapOpenPtySession(row) : null;
    },
  );
}

/** Mark a PTY closed (idempotent — a double close on a closed row is a no-op). */
export async function closePtySession(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sessionId: string;
    ptyId: string;
    identity: SandboxPtyProcessIdentity;
  },
): Promise<SandboxPtySessionRow | null> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      const [row] = await scopedDb
        .update(schema.sandboxPtySessions)
        .set({ status: "closed", closedAt: new Date() })
        .where(
          and(
            eq(schema.sandboxPtySessions.workspaceId, input.workspaceId),
            eq(schema.sandboxPtySessions.sessionId, input.sessionId),
            eq(schema.sandboxPtySessions.id, input.ptyId),
            eq(schema.sandboxPtySessions.status, "open"),
            ...exactPtyIdentityPredicates(input.identity),
          ),
        )
        .returning();
      return row ? mapPtySession(row) : null;
    },
  );
}

/** List a session's OPEN PTYs (reattach + reap). */
export async function listOpenPtySessions(
  db: Database,
  workspaceId: string,
  sessionId: string,
): Promise<SandboxOpenPtySessionRow[]> {
  return await withWorkspaceRls(db, workspaceId, async (scopedDb) => {
    const rows = await scopedDb
      .select()
      .from(schema.sandboxPtySessions)
      .where(
        and(
          eq(schema.sandboxPtySessions.workspaceId, workspaceId),
          eq(schema.sandboxPtySessions.sessionId, sessionId),
          eq(schema.sandboxPtySessions.status, "open"),
        ),
      )
      .orderBy(desc(schema.sandboxPtySessions.createdAt));
    return rows.map(mapOpenPtySession);
  });
}

// ============================================================================
// Sandbox singleton lease — the SOLE enforcer of one-box-per-group (P1.1).
//
// Group-keyed (workspace_id, sandbox_group_id) from the start. The sole
// double-spawn guard is the UNIQUE (workspace_id, sandbox_group_id) index +
// plain SELECT … FOR UPDATE (block, NOT skip-locked) + the cold->warming CAS
// inside that row lock. lease_epoch is integer (returns a JS number) but every
// read is Number()-coerced defensively. Mirrors the atomic turn-admission
// withWorkspaceRls/withRlsContext -> scopedDb.transaction -> tx.execute(sql<T>``)
// pattern (the row type goes on the sql tag, not on .execute).
// ============================================================================

export type SandboxLeaseLiveness = "cold" | "warming" | "warm" | "draining";
export type LeaseHolderKind = "turn" | "viewer" | "direct" | "process";

export type SandboxProviderExistence =
  | "not_created"
  | "creating"
  | "exists"
  | "missing"
  | "unknown";
export type SandboxArchiveAvailability = "none" | "available" | "unverified" | "invalid";
export type SandboxRestoreStatus =
  | "not_required"
  | "pending"
  | "restoring"
  | "verifying"
  | "ready"
  | "degraded"
  | "unrecoverable";
export type SandboxWorkspaceReadiness =
  | "unknown"
  | "not_ready"
  | "ready"
  | "degraded"
  | "unrecoverable";

export type SandboxTarArchiveRevision = TarWorkspaceArchiveDescriptor;
export type SandboxNativeSnapshotRevision = NativeSnapshotDescriptor;
export type SandboxArchiveRevision = WorkspaceArchiveDescriptor;

export type SandboxRecoveryState = {
  provider: {
    status: SandboxProviderExistence;
    instanceId: string | null;
    observedAt: string | null;
    diagnostic?: string;
  };
  archive: {
    status: SandboxArchiveAvailability;
    current: SandboxArchiveRevision | null;
    previous: SandboxArchiveRevision | null;
  };
  restore: {
    status: SandboxRestoreStatus;
    rematerializationId: string | null;
    selectedRevision: string | null;
    startedAt: string | null;
    completedAt: string | null;
    failureCode?: string;
    retryable?: boolean;
  };
  workspace: {
    status: SandboxWorkspaceReadiness;
    verifiedRevision: string | null;
    verifiedAt: string | null;
  };
};

// The snake_case raw shape returned by the raw sql`` lease queries. lease_epoch
// comes back as a number for an integer column, but we type it number|string
// and Number()-coerce so the same code is correct regardless of column type.
// Typed with an index signature so it satisfies db.execute<TRow extends
// Record<string, unknown>>.
type LeaseRow = {
  id: string;
  account_id: string;
  workspace_id: string;
  sandbox_group_id: string;
  liveness: SandboxLeaseLiveness;
  refcount: number;
  turn_holders: number;
  viewer_holders: number;
  instance_id: string | null;
  backend: string;
  os: string;
  image: string | null;
  rig_version_id: string | null;
  data_plane_url: string | null;
  terminal_data_plane_url: string | null;
  lease_epoch: number | string;
  workspace_generation: number | string;
  archive_generation: number | string | null;
  archive_capture_id: string | null;
  archive_capture_generation: number | string | null;
  archive_capture_started_at: Date | string | null;
  archive_capture_deadline_at: Date | string | null;
  resume_backend_id: string | null;
  resume_state: Record<string, unknown> | null;
  last_meter_at: Date | string | null;
  last_meter_tick: number;
  provider_created_at: Date | string | null;
  provider_deadline_at: Date | string | null;
  rotation_requested_at: Date | string | null;
  rotation_reason: "provider_deadline" | "operator" | null;
  current_checkpoint_artifact_id: string | null;
  previous_checkpoint_artifact_id: string | null;
  expires_at: Date | string;
} & Record<string, unknown>;

export interface LeaseSnapshot {
  id: string;
  sandboxGroupId: string;
  liveness: SandboxLeaseLiveness;
  refcount: number;
  turnHolders: number;
  viewerHolders: number;
  instanceId: string | null;
  backend: string;
  os: string;
  // The container image the group box runs (Modal image ref / docker image). Null
  // for a legacy/cold row (image unknown). Shared state: all the box's sessions run
  // this image; a resume resolving a different image conflicts (B3).
  image: string | null;
  // The frozen rig version the group box was created under (M3). Like `image`,
  // shared state: a resume resolving a DIFFERENT rig_version_id conflicts (solo
  // rotates through durable capture, N-holders throw SandboxRigConflictError). Null = rig unknown
  // (legacy/cold row or a rig-less session), which never conflicts.
  rigVersionId: string | null;
  dataPlaneUrl: string | null;
  // The cached ttyd pty-ws tunnel URL (7681), separate from dataPlaneUrl (the
  // 6080 desktop tunnel). Null until mintTerminalStream resolves + records it.
  terminalDataPlaneUrl: string | null;
  leaseEpoch: number;
  /** Monotonic filesystem mutation intent for the exact live workspace. */
  workspaceGeneration: number;
  /** Generation captured by the current verified archive, or null when no
   * generation-complete archive exists. */
  archiveGeneration: number | null;
  /** True only when the current verified archive represents the exact current
   * workspace generation. This is numeric/boolean truth, never archive content. */
  archiveComplete: boolean;
  /** Exact provider capture currently holding the lease-local admission gate. */
  archiveCapture: {
    id: string;
    workspaceGeneration: number;
    startedAt: Date;
    deadlineAt: Date;
  } | null;
  resumeBackendId: string | null;
  resumeState: Record<string, unknown> | null;
  /** Provider/archive/restore/workspace truth, deliberately separate from the
   * lease liveness and epoch fields above. Legacy envelopes project to
   * conservative unknown/unverified values. */
  recovery: SandboxRecoveryState;
  /** Conservative provider creation clock. Modal's hard timeout is measured
   * from this instant and cannot be extended by resume. */
  providerCreatedAt: Date | null;
  /** Durable deadline for replacing this physical provider instance. */
  providerDeadlineAt: Date | null;
  /** Once set, new holders and new filesystem mutations are fenced while the
   * current holders quiesce and the reaper creates a successor. */
  rotationRequestedAt: Date | null;
  rotationReason: "provider_deadline" | "operator" | null;
  currentCheckpointArtifactId: string | null;
  previousCheckpointArtifactId: string | null;
  expiresAt: Date;
}

export interface LiveModalSandboxLeaseAttribution {
  leaseId: string;
  workspaceId: string;
  sandboxGroupId: string;
  instanceId: string | null;
  liveness: SandboxLeaseLiveness;
}

export interface AcquireLeaseInput {
  accountId: string;
  workspaceId: string;
  // The group's identity (sessions.sandbox_group_id; == session id for a
  // singleton group). The lease is per-group, not per-session.
  sandboxGroupId: string;
  kind: LeaseHolderKind;
  // Globally unique durable turn-attempt id (turn) | viewer connection id
  // (viewer). A workflow-local activity id is not a valid turn holder id.
  holderId: string;
  subjectId?: string | null; // the attributing session within the group
  backend: string; // sessions.sandbox_backend
  os?: string; // default 'linux'
  // The container image this run resolves (Modal image ref / docker image). Stamped on
  // the cold-create + folded onto a warming/CAS; a warm/draining/warming box already
  // running a DIFFERENT image is a shared-state conflict (B3): a SOLO holder requests
  // durable capture-and-drain rotation, N-holders throw SandboxImageConflictError. Omitted
  // (null/undefined) -> image is not enforced (legacy/cold rows, selfhosted).
  image?: string | null;
  // The frozen rig version this run rides (M3). Stamped on the cold-create + CAS
  // and conflicted exactly like `image`: a live multi-holder box under a DIFFERENT
  // rig version throws SandboxRigConflictError; a solo holder requests durable
  // capture-and-drain rotation. Omitted (null/undefined) -> rig is not enforced (rig-less
  // sessions never stamp or conflict; legacy/cold rows read null = compatible).
  rigVersionId?: string | null;
  leaseTtlMs: number; // refresh window for expires_at (turn-heartbeat cadence)
  // Expiry stamped only while a cold->warming spawner is allowed to create the
  // provider box before any instance_id exists. Warm/draining/attached refreshes
  // must continue using leaseTtlMs.
  warmingLeaseTtlMs?: number;
  // Optional epoch fence for a re-establishing turn holder: when set, the
  // turn-arrival increment is gated on lease_epoch == expectedEpoch (split-brain).
  expectedEpoch?: number;
  /** Bounded wait for an exact provider-native capture claim to settle. The
   * transaction is released between retries; every retry re-reads the lease. */
  captureWaitMs?: number;
}

export type AcquireLeaseResult =
  // Caller WON the cold->warming CAS: it is the spawner (any pool worker). Must
  // resume-by-id from resume_state, expose the stream port, then call
  // commitWarmingToWarm. No owner process is started.
  | { role: "spawner"; lease: LeaseSnapshot }
  // Box live or being built by someone else: attach (and, for warming, wait).
  | { role: "attached"; lease: LeaseSnapshot }
  // Re-armed a draining lease back to warm (box never torn down).
  | { role: "rearmed"; lease: LeaseSnapshot }
  // Durable recovery truth says this cold group cannot safely materialize. No
  // holder is registered and no provider create is licensed.
  | {
      role: "blocked";
      code: "restore_degraded" | "restore_unrecoverable";
      lease: LeaseSnapshot;
    }
  // Epoch fence rejected the turn-arrival increment: a newer epoch exists (a
  // later turn re-established the box). Caller must back off and re-read; NEVER
  // create().
  | { role: "fenced"; lease: LeaseSnapshot };

// Thrown by callers that treat a fenced/superseded epoch as an error path.
export class SandboxLeaseSupersededError extends Error {
  constructor(
    public readonly sandboxGroupId: string,
    public readonly leaseEpoch: number,
  ) {
    super(`Sandbox lease superseded for group ${sandboxGroupId} (epoch ${leaseEpoch})`);
    this.name = "SandboxLeaseSupersededError";
  }
}

export type SandboxViewerForceDrainReason = "balance" | "warm_cap";

export class SandboxViewerAdmissionBlockedError extends Error {
  readonly name = "SandboxViewerAdmissionBlockedError";

  constructor(
    public readonly workspaceId: string,
    public readonly sandboxGroupId: string,
    public readonly reason: SandboxViewerForceDrainReason,
  ) {
    super(
      reason === "balance"
        ? "Sandbox viewer admission is blocked because the workspace has no managed credits"
        : "Sandbox viewer admission is blocked because the workspace warm allowance is exhausted",
    );
  }
}

export class SandboxLeaseRecoveryBlockedError extends Error {
  readonly name = "SandboxLeaseRecoveryBlockedError";

  constructor(
    public readonly sandboxGroupId: string,
    public readonly leaseEpoch: number,
    public readonly code: "restore_degraded" | "restore_unrecoverable",
    public readonly recovery: SandboxRecoveryState,
  ) {
    super(
      `Sandbox ${sandboxGroupId} recovery is ${code === "restore_degraded" ? "degraded" : "unrecoverable"} at epoch ${leaseEpoch}`,
    );
  }
}

// IMAGE IS SHARED STATE (B3): thrown when a resume resolves an image DIFFERENT from
// the one the live shared box was created with AND other holders are still on the box.
// A shared box is ONE filesystem; recreating it on a new image would yank the running
// filesystem out from under the OTHER sessions, so we refuse. The turn activity surfaces
// this as an actionable error: spawn with sandbox:'new' or align the pack image. A SOLO
// holder never hits this — acquireLease requests a reaper-owned durable rotation instead.
export class SandboxImageConflictError extends Error {
  constructor(
    public readonly sandboxGroupId: string,
    public readonly currentImage: string,
    public readonly requestedImage: string,
  ) {
    super(
      `Sandbox group ${sandboxGroupId} runs image ${currentImage}; this run resolves image ${requestedImage}. ` +
        `A shared box requires one image — spawn with sandbox:'new' for an isolated box or align the pack image.`,
    );
    this.name = "SandboxImageConflictError";
  }
}

// RIG IS SHARED STATE (M3): thrown when a resume resolves a rig version DIFFERENT from
// the one the live shared box was set up under AND other holders are still on the box.
// A rig bakes setup/tooling into the ONE shared filesystem; recreating it on a different
// rig would yank that filesystem out from under the other sessions, so we refuse. The
// turn activity surfaces this as an actionable error. A SOLO holder never hits this —
// acquireLease requests a reaper-owned durable rotation instead. Mirrors
// SandboxImageConflictError.
export class SandboxRigConflictError extends Error {
  constructor(
    public readonly sandboxGroupId: string,
    public readonly currentRigVersionId: string,
    public readonly requestedRigVersionId: string,
  ) {
    super(
      `Sandbox group ${sandboxGroupId} was set up for rig version ${currentRigVersionId}; this run resolves rig version ${requestedRigVersionId}. ` +
        `A shared box requires one rig — spawn with sandbox:'new' for an isolated box or bind the group's rig.`,
    );
    this.name = "SandboxRigConflictError";
  }
}

function mapLeaseRow(row: LeaseRow): LeaseSnapshot {
  const workspaceGeneration = Number(row.workspace_generation);
  const archiveGeneration = row.archive_generation === null ? null : Number(row.archive_generation);
  const recovery = recoveryStateFromLeaseRow(row);
  return {
    id: row.id,
    sandboxGroupId: row.sandbox_group_id,
    liveness: row.liveness,
    refcount: Number(row.refcount),
    turnHolders: Number(row.turn_holders),
    viewerHolders: Number(row.viewer_holders),
    instanceId: row.instance_id,
    backend: row.backend,
    os: row.os,
    image: row.image ?? null,
    rigVersionId: row.rig_version_id ?? null,
    dataPlaneUrl: row.data_plane_url,
    terminalDataPlaneUrl: row.terminal_data_plane_url ?? null,
    // Defensive coercion: integer returns a number, but coerce regardless so the
    // fence comparison stays exact even if the column type ever drifts to int8.
    leaseEpoch: Number(row.lease_epoch),
    workspaceGeneration,
    archiveGeneration,
    archiveComplete:
      recovery.archive.status === "available" &&
      archiveGeneration !== null &&
      archiveGeneration === workspaceGeneration,
    archiveCapture:
      row.archive_capture_id === null ||
      row.archive_capture_generation === null ||
      row.archive_capture_started_at === null ||
      row.archive_capture_deadline_at === null
        ? null
        : {
            id: row.archive_capture_id,
            workspaceGeneration: Number(row.archive_capture_generation),
            startedAt:
              row.archive_capture_started_at instanceof Date
                ? row.archive_capture_started_at
                : new Date(row.archive_capture_started_at),
            deadlineAt:
              row.archive_capture_deadline_at instanceof Date
                ? row.archive_capture_deadline_at
                : new Date(row.archive_capture_deadline_at),
          },
    resumeBackendId: row.resume_backend_id,
    resumeState: row.resume_state,
    recovery,
    providerCreatedAt:
      row.provider_created_at === null
        ? null
        : row.provider_created_at instanceof Date
          ? row.provider_created_at
          : new Date(row.provider_created_at),
    providerDeadlineAt:
      row.provider_deadline_at === null
        ? null
        : row.provider_deadline_at instanceof Date
          ? row.provider_deadline_at
          : new Date(row.provider_deadline_at),
    rotationRequestedAt:
      row.rotation_requested_at === null
        ? null
        : row.rotation_requested_at instanceof Date
          ? row.rotation_requested_at
          : new Date(row.rotation_requested_at),
    rotationReason: row.rotation_reason,
    currentCheckpointArtifactId: row.current_checkpoint_artifact_id,
    previousCheckpointArtifactId: row.previous_checkpoint_artifact_id,
    expiresAt: row.expires_at instanceof Date ? row.expires_at : new Date(row.expires_at),
  };
}

function hasCompleteWorkspaceArchive(row: LeaseRow): boolean {
  const workspaceGeneration = Number(row.workspace_generation);
  const archiveGeneration = row.archive_generation === null ? null : Number(row.archive_generation);
  return (
    recoveryStateFromLeaseRow(row).archive.status === "available" &&
    Number.isSafeInteger(workspaceGeneration) &&
    workspaceGeneration >= 0 &&
    archiveGeneration !== null &&
    Number.isSafeInteger(archiveGeneration) &&
    archiveGeneration === workspaceGeneration
  );
}

function parseArchiveRevision(value: unknown): SandboxArchiveRevision | null {
  return parseWorkspaceArchiveDescriptor(value);
}

function recoveryStateFromLeaseRow(row: LeaseRow): SandboxRecoveryState {
  const resume =
    row.resume_state && typeof row.resume_state === "object" ? row.resume_state : undefined;
  const sessionState =
    resume?.sessionState && typeof resume.sessionState === "object"
      ? (resume.sessionState as Record<string, unknown>)
      : undefined;
  const currentArchivePresent =
    typeof sessionState?.workspaceArchive === "string" && sessionState.workspaceArchive.length > 0;
  const previousArchivePresent =
    typeof sessionState?.workspaceArchivePrev === "string" &&
    sessionState.workspaceArchivePrev.length > 0;
  const current = parseArchiveRevision(sessionState?.workspaceArchiveMeta);
  const previous = parseArchiveRevision(sessionState?.workspaceArchivePrevMeta);
  const archiveStatus: SandboxArchiveAvailability = currentArchivePresent
    ? current
      ? "available"
      : "unverified"
    : previousArchivePresent
      ? "unverified"
      : "none";

  const explicit =
    resume?.opengeniRecovery && typeof resume.opengeniRecovery === "object"
      ? (resume.opengeniRecovery as Partial<SandboxRecoveryState>)
      : undefined;
  const providerInput = explicit?.provider;
  const restoreInput = explicit?.restore;
  const workspaceInput = explicit?.workspace;
  const providerStatus = providerInput?.status;
  const provider: SandboxRecoveryState["provider"] = {
    status:
      providerStatus === "not_created" ||
      providerStatus === "creating" ||
      providerStatus === "exists" ||
      providerStatus === "missing" ||
      providerStatus === "unknown"
        ? providerStatus
        : row.liveness === "warming"
          ? "creating"
          : row.instance_id
            ? "unknown"
            : "not_created",
    instanceId:
      typeof providerInput?.instanceId === "string" || providerInput?.instanceId === null
        ? providerInput.instanceId
        : row.instance_id,
    observedAt:
      typeof providerInput?.observedAt === "string" || providerInput?.observedAt === null
        ? providerInput.observedAt
        : null,
    ...(typeof providerInput?.diagnostic === "string"
      ? { diagnostic: providerInput.diagnostic }
      : {}),
  };
  const restoreStatus = restoreInput?.status;
  const restore: SandboxRecoveryState["restore"] = {
    status:
      restoreStatus === "not_required" ||
      restoreStatus === "pending" ||
      restoreStatus === "restoring" ||
      restoreStatus === "verifying" ||
      restoreStatus === "ready" ||
      restoreStatus === "degraded" ||
      restoreStatus === "unrecoverable"
        ? restoreStatus
        : row.liveness === "cold" && archiveStatus === "available"
          ? "pending"
          : row.liveness === "cold" && archiveStatus === "unverified"
            ? "degraded"
            : "not_required",
    rematerializationId:
      typeof restoreInput?.rematerializationId === "string"
        ? restoreInput.rematerializationId
        : null,
    selectedRevision:
      typeof restoreInput?.selectedRevision === "string" ? restoreInput.selectedRevision : null,
    startedAt: typeof restoreInput?.startedAt === "string" ? restoreInput.startedAt : null,
    completedAt: typeof restoreInput?.completedAt === "string" ? restoreInput.completedAt : null,
    ...(typeof restoreInput?.failureCode === "string"
      ? { failureCode: restoreInput.failureCode }
      : {}),
    ...(typeof restoreInput?.retryable === "boolean" ? { retryable: restoreInput.retryable } : {}),
  };
  const workspaceStatus = workspaceInput?.status;
  const workspace: SandboxRecoveryState["workspace"] = {
    status:
      workspaceStatus === "unknown" ||
      workspaceStatus === "not_ready" ||
      workspaceStatus === "ready" ||
      workspaceStatus === "degraded" ||
      workspaceStatus === "unrecoverable"
        ? workspaceStatus
        : row.liveness === "cold" && archiveStatus === "available"
          ? "not_ready"
          : row.liveness === "cold" && archiveStatus === "unverified"
            ? "degraded"
            : "unknown",
    verifiedRevision:
      typeof workspaceInput?.verifiedRevision === "string" ? workspaceInput.verifiedRevision : null,
    verifiedAt: typeof workspaceInput?.verifiedAt === "string" ? workspaceInput.verifiedAt : null,
  };
  return {
    provider,
    archive: { status: archiveStatus, current, previous },
    restore,
    workspace,
  };
}

function resumeStateWithRecovery(
  resumeState: Record<string, unknown> | null,
  recovery: SandboxRecoveryState,
): Record<string, unknown> {
  return { ...(resumeState ?? {}), opengeniRecovery: recovery };
}

const WORKSPACE_ARCHIVE_SESSION_KEYS = [
  "workspaceArchive",
  "workspaceArchiveMeta",
  "workspaceArchivePrev",
  "workspaceArchivePrevMeta",
  "workspaceArchiveAt",
] as const;

function resumeStateWithPreservedArchives(
  resumeState: Record<string, unknown> | null,
  archiveSource: Record<string, unknown> | null,
): Record<string, unknown> | null {
  const sourceSession =
    archiveSource?.sessionState && typeof archiveSource.sessionState === "object"
      ? (archiveSource.sessionState as Record<string, unknown>)
      : undefined;
  if (!sourceSession) return resumeState;
  const archiveFields: Record<string, unknown> = {};
  for (const key of WORKSPACE_ARCHIVE_SESSION_KEYS) {
    if (sourceSession[key] !== undefined && sourceSession[key] !== null) {
      archiveFields[key] = sourceSession[key];
    }
  }
  if (Object.keys(archiveFields).length === 0) return resumeState;
  const targetSession =
    resumeState?.sessionState && typeof resumeState.sessionState === "object"
      ? (resumeState.sessionState as Record<string, unknown>)
      : {};
  return {
    ...(resumeState ?? {}),
    ...(resumeState?.backendId === undefined && archiveSource?.backendId !== undefined
      ? { backendId: archiveSource.backendId }
      : {}),
    sessionState: { ...targetSession, ...archiveFields },
  };
}

function archiveOnlyResumeState(
  row: LeaseRow,
  recovery: SandboxRecoveryState,
): Record<string, unknown> {
  const current =
    row.resume_state && typeof row.resume_state === "object" ? row.resume_state : undefined;
  const currentSession =
    current?.sessionState && typeof current.sessionState === "object"
      ? (current.sessionState as Record<string, unknown>)
      : undefined;
  const sessionState: Record<string, unknown> = {};
  for (const key of WORKSPACE_ARCHIVE_SESSION_KEYS) {
    if (currentSession?.[key] !== undefined && currentSession[key] !== null) {
      sessionState[key] = currentSession[key];
    }
  }
  return {
    backendId:
      typeof current?.backendId === "string"
        ? current.backendId
        : (row.resume_backend_id ?? row.backend),
    ...(Object.keys(sessionState).length > 0 ? { sessionState } : {}),
    opengeniRecovery: recovery,
  };
}

function archiveProjectionFromResumeState(
  resumeState: Record<string, unknown> | null,
): SandboxRecoveryState["archive"] {
  const sessionState =
    resumeState?.sessionState && typeof resumeState.sessionState === "object"
      ? (resumeState.sessionState as Record<string, unknown>)
      : undefined;
  const currentPresent =
    typeof sessionState?.workspaceArchive === "string" && sessionState.workspaceArchive.length > 0;
  const previousPresent =
    typeof sessionState?.workspaceArchivePrev === "string" &&
    sessionState.workspaceArchivePrev.length > 0;
  const current = parseArchiveRevision(sessionState?.workspaceArchiveMeta);
  const previous = parseArchiveRevision(sessionState?.workspaceArchivePrevMeta);
  return {
    status: currentPresent
      ? current
        ? "available"
        : "unverified"
      : previousPresent
        ? "unverified"
        : "none",
    current,
    previous,
  };
}

// Recompute refcount/split-counts from the holder rows (holders are the source
// of truth), refresh expires_at, optionally set liveness. Returns the updated row.
async function recomputeAndStampLease(
  tx: Database,
  leaseId: string,
  leaseTtlMs: number,
  setLiveness: SandboxLeaseLiveness | null,
): Promise<LeaseRow> {
  const counts = await tx.execute<{
    total: number;
    turns: number;
    viewers: number;
  }>(sql`
    select count(*)::int as total,
           count(*) filter (where kind = 'turn')::int   as turns,
           count(*) filter (where kind = 'viewer')::int as viewers
    from sandbox_lease_holders where lease_id = ${leaseId}
  `);
  const c = counts[0]!;
  const updated = await tx.execute<LeaseRow>(sql`
    update sandbox_leases set
      refcount       = ${c.total},
      turn_holders   = ${c.turns},
      viewer_holders = ${c.viewers},
      expires_at     = now() + (${String(leaseTtlMs)} || ' milliseconds')::interval,
      ${setLiveness ? sql`liveness = ${setLiveness},` : sql``}
      updated_at     = now()
    where id = ${leaseId}
    returning *
  `);
  return updated[0]!;
}

// Idempotent acquire: the unique (lease, kind, holder) index makes a retried or
// duplicate acquire a no-op heartbeat refresh, never a double-count.
async function upsertLeaseHolder(
  tx: Database,
  leaseId: string,
  accountId: string,
  workspaceId: string,
  kind: LeaseHolderKind,
  holderId: string,
  subjectId: string | null,
): Promise<void> {
  await tx.execute(sql`
    insert into sandbox_lease_holders
      (account_id, workspace_id, lease_id, kind, holder_id, subject_id, last_heartbeat_at)
    values (${accountId}, ${workspaceId}, ${leaseId}, ${kind}, ${holderId}, ${subjectId}, now())
    on conflict (lease_id, kind, holder_id)
      do update set last_heartbeat_at = now()
  `);
}

// §4.1 — the get-or-create critical section. ONE transaction:
// insert-or-nothing -> SELECT … FOR UPDATE (block, not skip) -> branch -> bump.
// The single most load-bearing function: the sole double-spawn guard.
async function acquireLeaseOnce(
  db: Database,
  input: AcquireLeaseInput,
): Promise<AcquireLeaseResult> {
  if (input.kind === "process") {
    throw new Error("Process lease holders are created only by atomic retained-process promotion");
  }
  const { accountId, workspaceId, sandboxGroupId, kind, holderId, backend } = input;
  const os = input.os ?? "linux";
  const subjectId = input.subjectId ?? null;
  const warmingLeaseTtlMs = input.warmingLeaseTtlMs ?? input.leaseTtlMs;
  return await withRlsContext(
    db,
    { accountId, workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (txRaw) => {
        const tx = txRaw as unknown as Database;
        const image = input.image ?? null;
        const rigVersionId = input.rigVersionId ?? null;
        // (1) Materialize the singleton row if absent. ON CONFLICT DO NOTHING + the
        // unique index = idempotent under a race; concurrent inserts collapse to
        // one row. expires_at seeded so a never-warmed cold row has a valid TTL. The
        // image (B3) + rig version (M3) are stamped on the cold-create so a fresh box
        // records what it will be built on; a conflict on an EXISTING live box is
        // handled below.
        await tx.execute(sql`
        insert into sandbox_leases
          (account_id, workspace_id, sandbox_group_id, liveness, backend, os, image, rig_version_id, expires_at)
        values
          (${accountId}, ${workspaceId}, ${sandboxGroupId}, 'cold', ${backend}, ${os}, ${image}, ${rigVersionId},
           now() + (${String(input.leaseTtlMs)} || ' milliseconds')::interval)
        on conflict (workspace_id, sandbox_group_id) do nothing
      `);

        // (2) Serialize ALL concurrent arrivals on this group's row. Plain FOR
        // UPDATE (block, do NOT skip) — unlike concurrent enrollment scans,
        // because we WANT the loser to block then attach, not skip and lose.
        const rows = await tx.execute<LeaseRow & { draining_expired: boolean }>(sql`
        select *, (liveness = 'draining' and expires_at <= now()) as draining_expired
        from sandbox_leases
        where workspace_id = ${workspaceId} and sandbox_group_id = ${sandboxGroupId}
        for update
      `);
        const row = rows[0];
        if (!row) throw new Error(`Lease row vanished post-insert: ${sandboxGroupId}`);

        const liveness = row.liveness;

        // A workspace-wide billing/cap drain survives this lease becoming cold.
        // Viewer-only admission must consult it while holding the exact lease
        // row lock, otherwise a dashboard heartbeat can re-arm the draining box
        // between holder deletion and provider teardown. A live turn remains
        // viewable: the reaper intentionally drains only boxes with no turn
        // holder, and this same lock makes the distinction race-free.
        if (kind === "viewer" && Number(row.turn_holders) === 0) {
          const workspaceRows = await tx.execute<{
            sandbox_viewer_force_drain_reason: SandboxViewerForceDrainReason | null;
          }>(sql`
            select sandbox_viewer_force_drain_reason
            from workspaces
            where id = ${workspaceId}
          `);
          const reason = workspaceRows[0]?.sandbox_viewer_force_drain_reason ?? null;
          if (reason !== null) {
            throw new SandboxViewerAdmissionBlockedError(workspaceId, sandboxGroupId, reason);
          }
        }

        // Provider-native capture may temporarily pause the box. Do not attach
        // another holder while that operation owns the exact lease: the caller
        // retries after the claim clears, before it can reach the provider.
        if (row.archive_capture_id !== null) {
          return { role: "fenced" as const, lease: mapLeaseRow(row) };
        }

        // A finite-lifetime provider instance is already being replaced. Do not
        // admit another holder onto the old box: the current holders own its
        // quiescence, snapshot, and drain; every new arrival retries after the
        // cold->warming successor election.
        if (liveness !== "cold" && row.rotation_requested_at !== null) {
          return { role: "fenced" as const, lease: mapLeaseRow(row) };
        }

        // An expired DRAINING row is owned by the reaper's provider teardown,
        // not by a new arrival. In particular, do this before image/rig conflict
        // handling: a conflicting successor must not take the SOLO-recreate path
        // and clear the attributed instance while the reaper/old creator still
        // owns its termination. The row remains drainable until confirmDrainCold
        // settles it, so callers fail closed and retry after the box is cold.
        if (liveness === "draining" && row.draining_expired) {
          return { role: "fenced" as const, lease: mapLeaseRow(row) };
        }

        // -- SHARED STATE CONFLICT (B3 image + M3 rig): a LIVE box (warm/draining/warming)
        // was created under a specific image AND rig version. If this run resolves a
        // DIFFERENT image OR a DIFFERENT rig version (each checked only when both sides are
        // known), the one shared filesystem cannot serve both. Under the held row lock we
        // count the OTHER holders (not this exact (kind, holderId) — an idempotent retry of
        // our own holder is not a rival):
        //   - SOLO (no other holders): ROTATE. Preserve the attributed provider instance and
        //     durable checkpoint, request an immediate operator rotation, and fence this
        //     arrival. Its idempotent release drops the final holder; the sole reaper then
        //     captures /workspace, terminates the old provider, and confirms cold. A retry
        //     stamps the new image/rig only when it wins the cold successor election.
        //   - OTHER holders present: REFUSE. Throw — recreating would yank the running
        //     filesystem out from under the other sessions. Image conflict is reported first
        //     so its (pre-rig) error is unchanged for the image-only case.
        // Each axis is enforced only when BOTH sides are known; a cold row / a legacy null /
        // an unset input never conflicts (the selfhosted path passes neither; a rig-less run
        // passes no rigVersionId, so it never stamps or conflicts on rig).
        const imageConflict = image !== null && row.image !== null && row.image !== image;
        const rigConflict =
          rigVersionId !== null &&
          row.rig_version_id !== null &&
          row.rig_version_id !== rigVersionId;
        if (liveness !== "cold" && (imageConflict || rigConflict)) {
          const others = await tx.execute<{ n: number }>(sql`
          select count(*)::int as n from sandbox_lease_holders
          where lease_id = ${row.id} and not (kind = ${kind} and holder_id = ${holderId})
        `);
          const otherHolders = Number(others[0]?.n ?? 0);
          if (otherHolders > 0) {
            if (imageConflict) {
              throw new SandboxImageConflictError(
                sandboxGroupId,
                row.image as string,
                image as string,
              );
            }
            throw new SandboxRigConflictError(
              sandboxGroupId,
              row.rig_version_id as string,
              rigVersionId as string,
            );
          }
          // A live provider may be deleted only by the reaper after a verified
          // capture. Never manufacture a cold row or erase its provider/checkpoint
          // attribution here. Expiring the lease makes warming/draining conflicts
          // immediately eligible; a warm conflict reaches draining when the fenced
          // caller releases its exact final holder.
          const rotating = await tx.execute<LeaseRow>(sql`
          update sandbox_leases set
            rotation_requested_at = coalesce(rotation_requested_at, now()),
            rotation_reason = coalesce(rotation_reason, 'operator'),
            expires_at = least(expires_at, now()),
            updated_at = now()
          where id = ${row.id}
          returning *
        `);
          return {
            role: "fenced" as const,
            lease: mapLeaseRow(rotating[0] ?? row),
          };
        }

        // -- draining: late arrival re-arms (D1) only while the grace is open.
        // An expired row was fenced above because the reaper owns its provider
        // teardown and must not lose the attributed instance race.
        if (liveness === "draining") {
          await upsertLeaseHolder(tx, row.id, accountId, workspaceId, kind, holderId, subjectId);
          const updated = await recomputeAndStampLease(tx, row.id, input.leaseTtlMs, "warm");
          return { role: "rearmed" as const, lease: mapLeaseRow(updated) };
        }

        // -- cold: WIN the cold->warming CAS (C1). Exactly one winner under the
        // held row lock; concurrent arrivals serialize behind us and see warming.
        // The image (B3) is (re-)stamped on the CAS so the box the spawner cold-creates
        // records the image it runs — for a fresh cold row or a solo-recreate above.
        if (liveness === "cold") {
          const recovery = recoveryStateFromLeaseRow(row);
          if (
            (recovery.restore.status === "degraded" && recovery.restore.retryable !== true) ||
            recovery.restore.status === "unrecoverable"
          ) {
            return {
              role: "blocked" as const,
              code:
                recovery.restore.status === "degraded"
                  ? ("restore_degraded" as const)
                  : ("restore_unrecoverable" as const),
              lease: mapLeaseRow(row),
            };
          }
          const casRows = await tx.execute<{ id: string }>(sql`
          update sandbox_leases set
            liveness = 'warming',
            ${image !== null ? sql`image = ${image},` : sql``}
            ${rigVersionId !== null ? sql`rig_version_id = ${rigVersionId},` : sql``}
            updated_at = now()
          where id = ${row.id} and liveness = 'cold'
          returning id
        `);
          await upsertLeaseHolder(tx, row.id, accountId, workspaceId, kind, holderId, subjectId);
          const updated = await recomputeAndStampLease(tx, row.id, warmingLeaseTtlMs, null);
          // casRows.length === 0 cannot happen under the held row lock (defensive):
          // a lost CAS means a sibling flipped it first, so we attach.
          const role = casRows.length === 0 ? ("attached" as const) : ("spawner" as const);
          return { role, lease: mapLeaseRow(updated) };
        }

        // -- warm: epoch fence for re-establishing turn holders (split-brain). A
        // turn arriving with expectedEpoch must match the live row epoch; a stale
        // re-dispatched turn is fenced out -> back off, NEVER create(). Number()-
        // coerced so an int8 drift cannot make the compare always-true.
        if (
          liveness === "warm" &&
          kind === "turn" &&
          input.expectedEpoch !== undefined &&
          Number(row.lease_epoch) !== input.expectedEpoch
        ) {
          return { role: "fenced" as const, lease: mapLeaseRow(row) };
        }

        // -- warm / warming: attach (A2 / A1). refcount++ ONLY; never touch
        // liveness. The spawner exclusively owns warming->warm.
        // TTL: a WARMING attach must keep the warming budget — re-stamping the
        // plain (90s) TTL while a spawner's create() is still in flight would
        // collapse expires_at and let the warming-death reaper reset/drain the
        // lease before instance_id is recorded (F1). A WARM attach uses the plain
        // TTL as before.
        await upsertLeaseHolder(tx, row.id, accountId, workspaceId, kind, holderId, subjectId);
        const attachTtlMs = liveness === "warming" ? warmingLeaseTtlMs : input.leaseTtlMs;
        const updated = await recomputeAndStampLease(tx, row.id, attachTtlMs, null);
        return { role: "attached" as const, lease: mapLeaseRow(updated) };
      }),
  );
}

function waitForLeaseArchiveCapture(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function acquireLease(
  db: Database,
  input: AcquireLeaseInput,
): Promise<AcquireLeaseResult> {
  const captureWaitMs = input.captureWaitMs ?? 0;
  if (!Number.isSafeInteger(captureWaitMs) || captureWaitMs < 0 || captureWaitMs > 60 * 60_000) {
    throw new Error("Sandbox lease archive capture wait is invalid");
  }
  const deadline = Date.now() + captureWaitMs;
  let delayMs = 25;
  for (;;) {
    const result = await acquireLeaseOnce(db, input);
    if (
      result.role !== "fenced" ||
      result.lease.archiveCapture === null ||
      Date.now() >= deadline
    ) {
      return result;
    }
    await waitForLeaseArchiveCapture(Math.min(delayMs, Math.max(1, deadline - Date.now())));
    delayMs = Math.min(500, delayMs * 2);
  }
}

export type SandboxCheckpointRestoreArtifact = {
  id: string;
  providerBackend: string;
  providerBindingKey: string;
  providerBinding: Record<string, unknown>;
  objectKind: "modal_filesystem_snapshot" | "modal_directory_snapshot";
  objectId: string;
  descriptorRevision: string;
};

export type BeginSandboxRematerializationResult =
  | {
      status: "started";
      lease: LeaseSnapshot;
      /** Null is the explicit compatibility path for a verified legacy archive
       * that predates the checkpoint ledger. Newly published native snapshots
       * always carry this exact provider-ownership receipt. */
      checkpointArtifact: SandboxCheckpointRestoreArtifact | null;
    }
  | {
      status: "blocked";
      code:
        | "archive_unavailable"
        | "archive_unverified"
        | "archive_generation_mismatch"
        | "checkpoint_artifact_invalid"
        | "attempt_conflict"
        | "stale_epoch";
      lease: LeaseSnapshot | null;
    };

function validatedLegacyNativeSnapshotAdoption(
  value:
    | {
        archiveBase64: string;
        descriptor: SandboxNativeSnapshotRevision;
      }
    | null
    | undefined,
): { archiveBase64: string; descriptor: SandboxNativeSnapshotRevision } | null {
  if (!value || value.archiveBase64.length === 0 || value.archiveBase64.length % 4 !== 0) {
    return null;
  }
  let bytes: Uint8Array;
  try {
    bytes = Uint8Array.from(Buffer.from(value.archiveBase64, "base64"));
  } catch {
    return null;
  }
  if (Buffer.from(bytes).toString("base64") !== value.archiveBase64) return null;
  const descriptor = parseArchiveRevision(value.descriptor);
  const native = decodeNativeSnapshotRef(bytes);
  if (
    descriptor?.version !== 2 ||
    !native ||
    descriptor.archiveBytes !== bytes.length ||
    descriptor.archiveSha256 !== createHash("sha256").update(bytes).digest("hex") ||
    descriptor.provider !== native.provider ||
    descriptor.snapshotId !== native.snapshotId ||
    descriptor.workspacePersistence !== native.workspacePersistence
  ) {
    return null;
  }
  return { archiveBase64: value.archiveBase64, descriptor };
}

/** Records the single cold->warming winner's exact restore attempt. The lease
 * election remains the sole spawner guard; this adds durable selected-revision
 * and progress truth under the same epoch. */
export async function beginSandboxRematerialization(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sandboxGroupId: string;
    expectedEpoch: number;
    rematerializationId: string;
    /** Optional durable per-session fallback envelope. When the lease has no
     *  archive yet, its archive fields are imported under this same row lock so
     *  restoration can never consume bytes that were not durably selected by
     *  the lease attempt. Provider/session state is never imported here. */
    archiveSource?: Record<string, unknown> | null;
    /** One-time adoption of a native provider receipt written before the v2
     * descriptor split. The runtime derives v2 identity from the exact opaque
     * bytes. A metadata-less receipt is accepted only at generation zero; a v1
     * descriptor is accepted only when its byte hash and archive generation are
     * already current. Tar payloads and generation gaps remain ineligible. */
    legacyNativeArchive?: {
      archiveBase64: string;
      descriptor: SandboxNativeSnapshotRevision;
    } | null;
  },
): Promise<BeginSandboxRematerializationResult> {
  const legacyNativeArchive = validatedLegacyNativeSnapshotAdoption(input.legacyNativeArchive);
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (txRaw) => {
        const tx = txRaw as unknown as Database;
        const rows = await tx.execute<LeaseRow>(sql`
          select * from sandbox_leases
          where workspace_id = ${input.workspaceId}
            and sandbox_group_id = ${input.sandboxGroupId}
          for update
        `);
        const row = rows[0];
        if (!row || row.liveness !== "warming" || Number(row.lease_epoch) !== input.expectedEpoch) {
          return {
            status: "blocked" as const,
            code: "stale_epoch" as const,
            lease: row ? mapLeaseRow(row) : null,
          };
        }
        let workingResumeState = row.resume_state;
        let workingRow = row;
        let current = recoveryStateFromLeaseRow(workingRow);
        let importedArchiveGeneration = false;
        if (current.archive.status === "none" && input.archiveSource) {
          const imported = resumeStateWithPreservedArchives(
            workingResumeState,
            input.archiveSource,
          );
          if (imported !== workingResumeState) {
            workingResumeState = imported;
            workingRow = { ...workingRow, resume_state: imported };
            current = recoveryStateFromLeaseRow(workingRow);
            // A session fallback is the last verified archive from before the
            // lease acquired generation-aware ownership. Importing it is the
            // one-time protocol-v2 handoff: bind it to the currently locked
            // workspace generation in the same transaction that selects it.
            // Runtime still verifies the selected receipt/archive according to
            // its kind before the warming lease may commit warm.
            if (current.archive.status === "available" && current.archive.current) {
              workingRow = {
                ...workingRow,
                archive_generation: workingRow.workspace_generation,
              };
              importedArchiveGeneration = true;
            }
          }
        }
        if (legacyNativeArchive) {
          const sessionState =
            workingResumeState?.sessionState && typeof workingResumeState.sessionState === "object"
              ? (workingResumeState.sessionState as Record<string, unknown>)
              : null;
          const descriptor = legacyNativeArchive.descriptor;
          const existingDescriptor = parseArchiveRevision(sessionState?.workspaceArchiveMeta);
          const metadataLessGenerationZero =
            current.archive.status === "unverified" &&
            Number(workingRow.workspace_generation) === 0 &&
            workingRow.archive_generation === null;
          const v1DescriptorAlreadyCurrent =
            existingDescriptor?.version === 1 &&
            existingDescriptor.archiveBytes === descriptor.archiveBytes &&
            existingDescriptor.archiveSha256 === descriptor.archiveSha256 &&
            workingRow.archive_generation !== null &&
            Number(workingRow.archive_generation) === Number(workingRow.workspace_generation);
          if (
            (metadataLessGenerationZero || v1DescriptorAlreadyCurrent) &&
            backendForNativeSnapshotProvider(descriptor.provider) ===
              (workingRow.resume_backend_id ?? workingRow.backend) &&
            sessionState?.workspaceArchive === legacyNativeArchive.archiveBase64
          ) {
            const adoptedSessionState = {
              ...sessionState,
              workspaceArchiveMeta: descriptor,
            };
            workingResumeState = {
              ...(workingResumeState ?? {}),
              sessionState: adoptedSessionState,
            };
            workingRow = {
              ...workingRow,
              resume_state: workingResumeState,
              archive_generation: workingRow.workspace_generation,
            };
            current = recoveryStateFromLeaseRow(workingRow);
            importedArchiveGeneration = true;
          }
        }
        const archiveComplete = hasCompleteWorkspaceArchive(workingRow);
        if (
          current.archive.status !== "available" ||
          !current.archive.current ||
          !archiveComplete
        ) {
          if (current.archive.status !== "none") {
            const failedAt = new Date().toISOString();
            const failureCode =
              current.archive.status === "available" && !archiveComplete
                ? "archive_generation_mismatch"
                : "archive_unverified";
            const degraded: SandboxRecoveryState = {
              provider: {
                status: "not_created",
                instanceId: null,
                observedAt: failedAt,
              },
              archive: current.archive,
              restore: {
                status: "degraded",
                rematerializationId: null,
                selectedRevision: null,
                startedAt: null,
                completedAt: failedAt,
                failureCode,
                retryable: false,
              },
              workspace: {
                status: "degraded",
                verifiedRevision: null,
                verifiedAt: null,
              },
            };
            const degradedResumeState = resumeStateWithRecovery(workingResumeState, degraded);
            const degradedRows = await tx.execute<LeaseRow>(sql`
              update sandbox_leases set
                resume_state = ${JSON.stringify(degradedResumeState)}::jsonb,
                resume_backend_id = coalesce(resume_backend_id, backend),
                updated_at = now()
              where id = ${row.id}
                and liveness = 'warming'
                and lease_epoch = ${input.expectedEpoch}
              returning *
            `);
            workingRow = degradedRows[0] ?? workingRow;
          }
          return {
            status: "blocked" as const,
            code:
              current.archive.status === "none"
                ? ("archive_unavailable" as const)
                : current.archive.status === "available" && !archiveComplete
                  ? ("archive_generation_mismatch" as const)
                  : ("archive_unverified" as const),
            lease: mapLeaseRow(workingRow),
          };
        }
        let checkpointArtifact: SandboxCheckpointRestoreArtifact | null = null;
        if (workingRow.current_checkpoint_artifact_id !== null) {
          const artifactRows = await tx.execute<{
            id: string;
            account_id: string;
            workspace_id: string;
            sandbox_group_id: string;
            source_lease_id: string;
            source_workspace_generation: number | string | null;
            provenance: "native_capture" | "legacy_provider_adopted";
            provider_backend: string;
            provider_binding_key: string;
            provider_binding: Record<string, unknown>;
            object_kind: string;
            object_id: string;
            archive_base64: string;
            descriptor: unknown;
            descriptor_revision: string;
            state: string;
          }>(sql`
            select id, account_id, workspace_id, sandbox_group_id,
              source_lease_id, source_workspace_generation, provenance, provider_backend,
              provider_binding_key, provider_binding, object_kind, object_id,
              archive_base64, descriptor, descriptor_revision, state
            from sandbox_checkpoint_artifacts
            where id = ${workingRow.current_checkpoint_artifact_id}
            for share
          `);
          const artifact = artifactRows[0];
          const descriptor = parseArchiveRevision(artifact?.descriptor);
          const providerIdentity = canonicalModalCheckpointProviderBinding(
            artifact?.provider_binding,
          );
          const sessionState =
            workingResumeState?.sessionState && typeof workingResumeState.sessionState === "object"
              ? (workingResumeState.sessionState as Record<string, unknown>)
              : null;
          const selected = current.archive.current;
          const expectedObjectKind =
            selected.version === 2 && selected.provider === "modal_snapshot_filesystem"
              ? "modal_filesystem_snapshot"
              : selected.version === 2 && selected.provider === "modal_snapshot_directory"
                ? "modal_directory_snapshot"
                : null;
          const valid =
            artifact !== undefined &&
            selected.version === 2 &&
            descriptor?.version === 2 &&
            expectedObjectKind !== null &&
            artifact.state === "current" &&
            artifact.account_id === input.accountId &&
            artifact.workspace_id === input.workspaceId &&
            artifact.sandbox_group_id === input.sandboxGroupId &&
            artifact.source_lease_id === workingRow.id &&
            ((artifact.provenance === "native_capture" &&
              artifact.source_workspace_generation !== null &&
              Number(artifact.source_workspace_generation) ===
                Number(workingRow.workspace_generation)) ||
              (artifact.provenance === "legacy_provider_adopted" &&
                artifact.source_workspace_generation === null)) &&
            artifact.provider_backend === workingRow.backend &&
            artifact.provider_backend === backendForNativeSnapshotProvider(selected.provider) &&
            providerIdentity !== null &&
            providerIdentity.key === artifact.provider_binding_key &&
            artifact.object_kind === expectedObjectKind &&
            artifact.object_id === selected.snapshotId &&
            artifact.archive_base64 === sessionState?.workspaceArchive &&
            artifact.descriptor_revision === selected.revision &&
            descriptor.revision === selected.revision &&
            descriptor.archiveSha256 === selected.archiveSha256 &&
            descriptor.archiveBytes === selected.archiveBytes &&
            descriptor.provider === selected.provider &&
            descriptor.snapshotId === selected.snapshotId &&
            descriptor.workspacePersistence === selected.workspacePersistence;
          if (!valid) {
            const failedAt = new Date().toISOString();
            const degraded: SandboxRecoveryState = {
              provider: {
                status: "not_created",
                instanceId: null,
                observedAt: failedAt,
              },
              archive: current.archive,
              restore: {
                status: "degraded",
                rematerializationId: null,
                selectedRevision: null,
                startedAt: null,
                completedAt: failedAt,
                failureCode: "checkpoint_artifact_invalid",
                retryable: false,
              },
              workspace: {
                status: "degraded",
                verifiedRevision: null,
                verifiedAt: null,
              },
            };
            const degradedRows = await tx.execute<LeaseRow>(sql`
              update sandbox_leases set
                resume_state = ${JSON.stringify(
                  resumeStateWithRecovery(workingResumeState, degraded),
                )}::jsonb,
                resume_backend_id = coalesce(resume_backend_id, backend),
                updated_at = now()
              where id = ${row.id}
                and liveness = 'warming'
                and lease_epoch = ${input.expectedEpoch}
              returning *
            `);
            return {
              status: "blocked" as const,
              code: "checkpoint_artifact_invalid" as const,
              lease: mapLeaseRow(degradedRows[0] ?? workingRow),
            };
          }
          checkpointArtifact = {
            id: artifact.id,
            providerBackend: artifact.provider_backend,
            providerBindingKey: artifact.provider_binding_key,
            providerBinding: providerIdentity.binding,
            objectKind: artifact.object_kind as SandboxCheckpointRestoreArtifact["objectKind"],
            objectId: artifact.object_id,
            descriptorRevision: artifact.descriptor_revision,
          };
        }
        if (
          (current.restore.status === "restoring" || current.restore.status === "verifying") &&
          current.restore.rematerializationId !== input.rematerializationId
        ) {
          return {
            status: "blocked" as const,
            code: "attempt_conflict" as const,
            lease: mapLeaseRow(row),
          };
        }
        if (
          (current.restore.status === "restoring" || current.restore.status === "verifying") &&
          current.restore.rematerializationId === input.rematerializationId
        ) {
          return {
            status: "started" as const,
            lease: mapLeaseRow(row),
            checkpointArtifact,
          };
        }
        const startedAt = new Date().toISOString();
        const recovery: SandboxRecoveryState = {
          provider: {
            status: "creating",
            instanceId: null,
            observedAt: startedAt,
          },
          archive: current.archive,
          restore: {
            status: "restoring",
            rematerializationId: input.rematerializationId,
            selectedRevision: current.archive.current.revision,
            startedAt,
            completedAt: null,
          },
          workspace: {
            status: "not_ready",
            verifiedRevision: null,
            verifiedAt: null,
          },
        };
        const resumeStateJson = JSON.stringify(
          resumeStateWithRecovery(workingResumeState, recovery),
        );
        const updated = await tx.execute<LeaseRow>(sql`
          update sandbox_leases set
            resume_state = ${resumeStateJson}::jsonb,
            ${importedArchiveGeneration ? sql`archive_generation = workspace_generation,` : sql``}
            updated_at = now()
          where id = ${row.id}
            and liveness = 'warming'
            and lease_epoch = ${input.expectedEpoch}
          returning *
        `);
        return updated[0]
          ? {
              status: "started" as const,
              lease: mapLeaseRow(updated[0]),
              checkpointArtifact,
            }
          : {
              status: "blocked" as const,
              code: "stale_epoch" as const,
              lease: null,
            };
      }),
  );
}

export async function markSandboxRestoreVerifying(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sandboxGroupId: string;
    expectedEpoch: number;
    rematerializationId: string;
  },
): Promise<{ wrote: boolean }> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) => {
      const rows = await scopedDb.execute<{ id: string }>(sql`
        update sandbox_leases set
          resume_state = jsonb_set(resume_state, '{opengeniRecovery,restore,status}', '"verifying"'::jsonb),
          updated_at = now()
        where workspace_id = ${input.workspaceId}
          and sandbox_group_id = ${input.sandboxGroupId}
          and liveness = 'warming'
          and lease_epoch = ${input.expectedEpoch}
          and resume_state #>> '{opengeniRecovery,restore,rematerializationId}' = ${input.rematerializationId}
          and resume_state #>> '{opengeniRecovery,restore,status}' = 'restoring'
        returning id
      `);
      return { wrote: rows.length > 0 };
    },
  );
}

export async function failSandboxRematerialization(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sandboxGroupId: string;
    expectedEpoch: number;
    rematerializationId: string;
    failureCode: string;
    retryable: boolean;
  },
): Promise<{ failed: boolean; lease: LeaseSnapshot | null }> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (txRaw) => {
        const tx = txRaw as unknown as Database;
        const rows = await tx.execute<LeaseRow>(sql`
          select * from sandbox_leases
          where workspace_id = ${input.workspaceId}
            and sandbox_group_id = ${input.sandboxGroupId}
          for update
        `);
        const row = rows[0];
        if (
          !row ||
          row.liveness !== "warming" ||
          Number(row.lease_epoch) !== input.expectedEpoch ||
          (
            row.resume_state as {
              opengeniRecovery?: {
                restore?: { rematerializationId?: unknown };
              };
            }
          )?.opengeniRecovery?.restore?.rematerializationId !== input.rematerializationId
        ) {
          return { failed: false, lease: row ? mapLeaseRow(row) : null };
        }
        const current = recoveryStateFromLeaseRow(row);
        const terminalStatus: SandboxRestoreStatus = input.retryable ? "degraded" : "unrecoverable";
        const recovery: SandboxRecoveryState = {
          provider: {
            status: "missing",
            instanceId: row.instance_id,
            observedAt: new Date().toISOString(),
          },
          archive: current.archive,
          restore: {
            ...current.restore,
            status: terminalStatus,
            completedAt: new Date().toISOString(),
            failureCode: input.failureCode.slice(0, 96),
            retryable: input.retryable,
          },
          workspace: {
            status: input.retryable ? "degraded" : "unrecoverable",
            verifiedRevision: null,
            verifiedAt: null,
          },
        };
        const resumeStateJson = JSON.stringify(archiveOnlyResumeState(row, recovery));
        const updated = await tx.execute<LeaseRow>(sql`
          update sandbox_leases set
            liveness = 'cold',
            instance_id = null,
            data_plane_url = null,
            terminal_data_plane_url = null,
            lease_epoch = lease_epoch + 1,
            resume_state = ${resumeStateJson}::jsonb,
            provider_created_at = null,
            provider_deadline_at = null,
            rotation_requested_at = null,
            rotation_reason = null,
            archive_capture_id = null,
            archive_capture_generation = null,
            archive_capture_started_at = null,
            archive_capture_deadline_at = null,
            updated_at = now()
          where id = ${row.id}
            and liveness = 'warming'
            and lease_epoch = ${input.expectedEpoch}
          returning *
        `);
        return updated[0]
          ? { failed: true, lease: mapLeaseRow(updated[0]) }
          : { failed: false, lease: null };
      }),
  );
}

export async function markSandboxProviderReady(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sandboxGroupId: string;
    expectedEpoch: number;
    expectedInstanceId: string;
  },
): Promise<{ wrote: boolean; lease: LeaseSnapshot | null }> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (txRaw) => {
        const tx = txRaw as unknown as Database;
        const rows = await tx.execute<LeaseRow>(sql`
          select * from sandbox_leases
          where workspace_id = ${input.workspaceId}
            and sandbox_group_id = ${input.sandboxGroupId}
          for update
        `);
        const row = rows[0];
        if (
          !row ||
          row.liveness !== "warm" ||
          Number(row.lease_epoch) !== input.expectedEpoch ||
          row.instance_id !== input.expectedInstanceId
        ) {
          return { wrote: false, lease: row ? mapLeaseRow(row) : null };
        }
        const current = recoveryStateFromLeaseRow(row);
        const observedAt = new Date().toISOString();
        const recovery: SandboxRecoveryState = {
          ...current,
          provider: {
            status: "exists",
            instanceId: row.instance_id,
            observedAt,
          },
          restore:
            current.restore.status === "ready"
              ? current.restore
              : {
                  status: "not_required",
                  rematerializationId: null,
                  selectedRevision: null,
                  startedAt: null,
                  completedAt: observedAt,
                },
          workspace:
            current.restore.status === "ready"
              ? current.workspace
              : {
                  status: "ready",
                  verifiedRevision: null,
                  verifiedAt: observedAt,
                },
        };
        const resumeStateJson = JSON.stringify(resumeStateWithRecovery(row.resume_state, recovery));
        const updated = await tx.execute<LeaseRow>(sql`
          update sandbox_leases set resume_state = ${resumeStateJson}::jsonb, updated_at = now()
          where id = ${row.id}
            and liveness = 'warm'
            and lease_epoch = ${input.expectedEpoch}
            and instance_id = ${input.expectedInstanceId}
          returning *
        `);
        return updated[0]
          ? { wrote: true, lease: mapLeaseRow(updated[0]) }
          : { wrote: false, lease: null };
      }),
  );
}

// §4.2 — the warming publication lease_epoch++ site. Loss, failed restore, and
// drain transitions also advance the epoch under their own exact predicates.
// CAS on (warming AND lease_epoch=expected) and fold the group box envelope
// (resume_backend_id/resume_state) onto the lease.
export async function commitWarmingToWarm(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sandboxGroupId: string;
    expectedEpoch: number; // the epoch the spawner observed at cold->warming
    instanceId: string;
    dataPlaneUrl?: string | null; // event-driven resolveExposedPort result, any worker
    resumeBackendId?: string | null;
    resumeState?: Record<string, unknown> | null;
    /** Required when the warming lease carries a selected durable archive.
     *  The warm transition is rejected unless this exact attempt is in the
     *  verifying state for this exact revision. */
    rematerialization?: {
      id: string;
      verifiedRevision: string;
    };
    leaseTtlMs: number;
  },
): Promise<{
  committed: boolean;
  lease: LeaseSnapshot | null;
  reason?:
    | "stale_epoch"
    | "rematerialization_required"
    | "rematerialization_mismatch"
    | "archive_revision_mismatch"
    | "archive_generation_mismatch";
}> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (txRaw) => {
        const tx = txRaw as unknown as Database;
        const rows = await tx.execute<LeaseRow>(sql`
          select * from sandbox_leases
          where workspace_id = ${input.workspaceId}
            and sandbox_group_id = ${input.sandboxGroupId}
          for update
        `);
        const row = rows[0];
        if (!row || row.liveness !== "warming" || Number(row.lease_epoch) !== input.expectedEpoch) {
          return {
            committed: false,
            lease: row ? mapLeaseRow(row) : null,
            reason: "stale_epoch" as const,
          };
        }

        const current = recoveryStateFromLeaseRow(row);
        const rematerialization = input.rematerialization;
        if (current.archive.status === "available" && !rematerialization) {
          return {
            committed: false,
            lease: mapLeaseRow(row),
            reason: "rematerialization_required" as const,
          };
        }
        if (
          rematerialization &&
          (current.restore.status !== "verifying" ||
            current.restore.rematerializationId !== rematerialization.id ||
            current.restore.selectedRevision !== rematerialization.verifiedRevision)
        ) {
          return {
            committed: false,
            lease: mapLeaseRow(row),
            reason: "rematerialization_mismatch" as const,
          };
        }
        if (
          rematerialization &&
          current.archive.current?.revision !== rematerialization.verifiedRevision
        ) {
          return {
            committed: false,
            lease: mapLeaseRow(row),
            reason: "archive_revision_mismatch" as const,
          };
        }
        if (rematerialization && !hasCompleteWorkspaceArchive(row)) {
          return {
            committed: false,
            lease: mapLeaseRow(row),
            reason: "archive_generation_mismatch" as const,
          };
        }

        const completedAt = new Date().toISOString();
        const recovery: SandboxRecoveryState = rematerialization
          ? {
              provider: {
                status: "exists",
                instanceId: input.instanceId,
                observedAt: completedAt,
              },
              archive: current.archive,
              restore: {
                status: "ready",
                rematerializationId: rematerialization.id,
                selectedRevision: rematerialization.verifiedRevision,
                startedAt: current.restore.startedAt,
                completedAt,
              },
              workspace: {
                status: "ready",
                verifiedRevision: rematerialization.verifiedRevision,
                verifiedAt: completedAt,
              },
            }
          : {
              provider: {
                status: "exists",
                instanceId: input.instanceId,
                observedAt: completedAt,
              },
              archive: archiveProjectionFromResumeState(input.resumeState ?? null),
              restore: {
                status: "not_required",
                rematerializationId: null,
                selectedRevision: null,
                startedAt: null,
                completedAt,
              },
              workspace: {
                status: "ready",
                verifiedRevision: null,
                verifiedAt: completedAt,
              },
            };
        const withArchives = resumeStateWithPreservedArchives(
          input.resumeState ?? null,
          row.resume_state,
        );
        const resumeStateJson = JSON.stringify(resumeStateWithRecovery(withArchives, recovery));
        const updated = await tx.execute<LeaseRow>(sql`
          update sandbox_leases set
            liveness          = 'warm',
            instance_id       = ${input.instanceId},
            data_plane_url    = ${input.dataPlaneUrl ?? null},
            terminal_data_plane_url = null,
            resume_backend_id = ${input.resumeBackendId ?? null},
            resume_state      = ${resumeStateJson}::jsonb,
            lease_epoch       = lease_epoch + 1,
            expires_at        = now() + (${String(input.leaseTtlMs)} || ' milliseconds')::interval,
            updated_at        = now()
          where id = ${row.id}
            and liveness = 'warming'
            and lease_epoch = ${input.expectedEpoch}
          returning *
        `);
        if (!updated[0]) {
          return {
            committed: false,
            lease: null,
            reason: "stale_epoch" as const,
          };
        }
        return { committed: true, lease: mapLeaseRow(updated[0]) };
      }),
  );
}

// §4.2a — leak-proof create attribution. The spawner calls this immediately
// after the provider create returns, before display/readiness/setup work. It
// intentionally does NOT bump lease_epoch or mark the lease warm; it only makes
// the just-created provider id durable while the row is still warming so a
// failure/reaper/provider-side sweep can identify and stop it.
export async function recordWarmingSandboxCreated(
  db: Database,
  input: {
    accountId: string;
    workspaceId: string;
    sandboxGroupId: string;
    expectedEpoch: number;
    /** Exact restore attempt elected before provider create. Null for a fresh
     *  archive-less create. Provider attribution is accepted only while the
     *  warming row still carries this same attempt as well as this epoch. */
    rematerializationId?: string | null;
    instanceId: string;
    resumeBackendId?: string | null;
    resumeState?: Record<string, unknown> | null;
    /** Conservative provider-call start, not callback completion. Required as
     * a pair for finite-lifetime providers such as Modal. */
    providerCreatedAt?: Date | null;
    providerDeadlineAt?: Date | null;
    leaseTtlMs: number;
    /** The still-WARMING lease must keep the warming budget after create() returns:
     *  provider manifest hydration and commitWarmingToWarm can exceed the 90s turn
     *  TTL and trip the warming-death (c2) drain now that instance_id is set.
     *  Desktop/display work is not part of warming; it is initialized lazily by
     *  viewer attach or actual computer-use. Defaults to leaseTtlMs for callers. */
    warmingLeaseTtlMs?: number;
  },
): Promise<{ recorded: boolean; lease: LeaseSnapshot | null }> {
  return await withRlsContext(
    db,
    { accountId: input.accountId, workspaceId: input.workspaceId },
    async (scopedDb) =>
      await scopedDb.transaction(async (txRaw) => {
        const tx = txRaw as unknown as Database;
        const rows = await tx.execute<LeaseRow>(sql`
          select * from sandbox_leases
          where workspace_id = ${input.workspaceId}
            and sandbox_group_id = ${input.sandboxGroupId}
          for update
        `);
        const row = rows[0];
        if (!row || row.liveness !== "warming" || Number(row.lease_epoch) !== input.expectedEpoch) {
          return { recorded: false, lease: row ? mapLeaseRow(row) : null };
        }
        const now = new Date().toISOString();
        const current = recoveryStateFromLeaseRow(row);
        if (current.restore.rematerializationId !== (input.rematerializationId ?? null)) {
          return { recorded: false, lease: mapLeaseRow(row) };
        }
        const recovery: SandboxRecoveryState = {
          ...current,
          provider: {
            status: "creating",
            instanceId: input.instanceId,
            observedAt: now,
          },
          workspace: {
            ...current.workspace,
            status: "not_ready",
            verifiedRevision: null,
            verifiedAt: null,
          },
        };
        const withArchives = resumeStateWithPreservedArchives(
          input.resumeState ?? null,
          row.resume_state,
        );
        const resumeStateJson = JSON.stringify(resumeStateWithRecovery(withArchives, recovery));
        const warmingTtlMs = input.warmingLeaseTtlMs ?? input.leaseTtlMs;
        const providerCreatedAt = input.providerCreatedAt ?? null;
        const providerDeadlineAt = input.providerDeadlineAt ?? null;
        if ((providerCreatedAt === null) !== (providerDeadlineAt === null)) {
          throw new Error("Provider creation and deadline timestamps must be supplied together");
        }
        if (
          providerCreatedAt &&
          providerDeadlineAt &&
          providerDeadlineAt.getTime() <= providerCreatedAt.getTime()
        ) {
          throw new Error("Provider deadline must be later than provider creation");
        }
        const updated = await tx.execute<LeaseRow>(sql`
          update sandbox_leases set
            instance_id       = ${input.instanceId},
            resume_backend_id = ${input.resumeBackendId ?? null},
            resume_state      = ${resumeStateJson}::jsonb,
            provider_created_at = ${providerCreatedAt?.toISOString() ?? null}::timestamptz,
            provider_deadline_at = ${providerDeadlineAt?.toISOString() ?? null}::timestamptz,
            rotation_requested_at = null,
            rotation_reason = null,
            expires_at        = now() + (${String(warmingTtlMs)} || ' milliseconds')::interval,
            updated_at        = now()
          where id = ${row.id}
            and liveness = 'warming'
            and lease_epoch = ${input.expectedEpoch}
          returning *
        `);
        return updated[0]
          ? { recorded: true, lease: mapLeaseRow(updated[0]) }
          : { recorded: false, lease: null };
      }),
  );
}

